nodes.statement:
A causal DAG $\g[D] = (\mb{V,E})$ is a \textit{causal Bayesian network compatible with} $\mb{F^*}$ if and only if for all $f(\mb{v} | do(\mb{x})) \in \mb{F^*}$, the following \textit{truncated factorization} holds:
\begin{align}
    f(\mb{v} | do(\mb{x})) = \prod_{V_i \in \mb{V} \setminus \mb{X}} f(v_i|\mathrm{pa}(v_i,\g[D])) \mathbbm{1}(\mb{X} = \mb{x}) \end{align}
\citep{pearl2009causality, bareinboim2012local}.

{\normalfont (\textbf{Bucket}; \citealp{perkovic2020identifying})}
    Let $\mb{B}$ and $\mb{D}$ be node sets in an MPDAG $\g$ such that $\mb{B} \subseteq \mb{D}$. Then $\mb{B}$ is a bucket in $\mb{D}$ given $\g$ if it is the intersection of $\mb{D}$ with a maximal undirected connected set in $\g$. That is,
    \begin{itemize}
        \item $\g$ contains a undirected path from $B_i$ to $B_j$ for every $B_i, B_j \in \mb{B}$, and  
        \item $\g$ contains no undirected path from $\mb{B}$ to any node in $\mb{D} \setminus \mb{B}$.
    \end{itemize}

Let $\mb{D}$ be a node set in an MPDAG $\g$. Then $(\mb{B_1}, \dots, \mb{B_k}), k \ge 1$, is an ordered bucket decomposition of $\mb{D}$ in $\g$ if
    \begin{itemize}
        \item $\mb{B_i}$ is a bucket in $\mb{D}$ given $\g$ for all $i \in \{ 1, \dots, k\}$.
        \item $\mb{B_1} < \dots < \mb{B_k}$ is a partial causal ordering of $\mb{D}$ consistent with $\g$ so that
        \begin{itemize}
            \item $\cup_{i=1}^k \mb{B_i} = \mb{D}$, and
            \item any edge in $\g$ between $B_i \in \mb{B_i}$ and $B_j \in \mb{B_j}$ for $i,j \in \{1, \dots, k\}$, $i<j$, must take the form $B_i \to B_j$.
        \end{itemize}
    \end{itemize}

Let $\mb{X}$, $\mb{Y}$, and $\mb{Z}$ be pairwise disjoint node sets in a causal MPDAG $\g =(\mb{V,E})$, where $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$ and where there is no proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ that starts with an undirected edge. Then for any density $f$ consistent with $\g$,
    \begin{align}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z}) = \int \prod_{i\in \mb{I_E}} f(\mb{b_i} \,|\, \mathrm{pa}(\mb{b_i},\g)) \prod_{i \in \mb{I_N}} f(\mb{b_i} \,|\, \mb{b_i^N}, \mb{z}) \ \mathop{}\!\mathrm{d} \mb{b}, \end{align}
    for ${\mb{B} =\mathrm{An}(\mb{Y}, \g_{\mb{V} \setminus \mb{X}}) \setminus (\mb{Z} \cup \mb{Y})}$; ${(\mb{B_1}, \dots, \mb{B_k}) = \mathrm{PCO}(\mathrm{An}(\mb{Y}, \g_{\mb{V} \setminus \mb{X}}) \setminus \mb{Z}, \g)}$; ${\mb{B_0} = \emptyset}$; and $\mb{B_i^N}= \cup_{j=0}^{i-1}\mb{B_j} \setminus \mathrm{PossDe}(\mb{X},\g)$. For ${i \in \{1, \dots, k\}}$, let ${i \in \mb{I_E}}$ when ${\mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset}$ and let ${i \in \mb{I_N}}$ otherwise.

conclusions:
for any density $f$ consistent with $\g$,
    \begin{align}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z}) = \int \prod_{i\in \mb{I_E}} f(\mb{b_i} \,|\, \mathrm{pa}(\mb{b_i},\g)) \prod_{i \in \mb{I_N}} f(\mb{b_i} \,|\, \mb{b_i^N}, \mb{z}) \ \mathop{}\!\mathrm{d} \mb{b}, \label{eq:id-formula}
    \end{align}

