\begin{split}
            f(\mb{y} | do(\mb{z}), \mb{w}, do(\mb{x})) = f(\mb{y} | \mb{w}, do(\mb{x})),
        \end{split}

Let $\g$ be the causal MPDAG in Figure \ref{fig:ex-rules1+2}, and suppose we want to identify the causal effect of $X$ on $Y$ given $\{V_1,V_2\}$. Note that we cannot use Theorem \ref{thm:id-formula}, since $\{V_1,V_2\} \cap \mathrm{PossDe}(X, \g) \neq \emptyset$. However, we can use Theorem \ref{thm:do-calc-mpdag} to show
    \begin{align*}
        f(y \,|\, do(x), v_1, v_2)
            &= f(y \,|\, x, v_1, v_2).
    \end{align*}
    The equality follows from Rule 2, since $Y \perp_{d} X \,|\, V_1, V_2$ in $\g_{\underline{\mb{X}}}$.

Let $\g$ be a causal MPDAG containing only $X - Z \to Y$, and suppose we want to identify the causal effect of $X$ on $Y$ given $Z$. Note that we cannot use Theorems \ref{thm:id-formula} or \ref{thm:id-rule3}, since $Z \in \mathrm{PossDe}(X, \g)$. However, we can use Theorem \ref{thm:do-calc-mpdag} to show
    \begin{align*}
        f(y \,|\, do(x), z)
            &= f(y \,|\, z).
    \end{align*}    
    This holds by Rule 3, since $Y \perp_{d} X \,|\, Z$ in $\g_{\overline{\mb{X}}}$.

\vspace{.3cm}
    \Input{Disjoint node sets $\mb{X}, \mb{Y}, \mb{Z} \subseteq \mb{V}$ and causal MPDAG $\g=(\mb{V,E})$}
    \Output{Expression for $f(\mb{y} \,|\, do(\mb{x}), \mb{z})$, for any $f$ consistent with $\g$, or FAIL}
    \vspace{.3cm}
    \SetAlgoVlined
    Let $\mb{Z'} =  \mb{Z}$ and $\mb{X'} = \mb{X}$;\\ \vskip .2cm
    \While{
    $\exists$ a proper possibly causal path $\mb{X'}$ to $\mb{Y} \cup \mb{Z'}$ in $\g$ that starts undirected }{
        Pick $X \in \mb{X'}$ on such a path;\\
        \uIf{
        $(\, \mb{Y} \perp_{d} X \,\,|\,\, \mb{X'} \setminus \{X\}, \mb{Z'} \,)_{\, \g_{\overline{\mb{X'} \setminus \{X\}} \underline{X}}}$}{
            Add $X$ to $\mb{Z'}$;
                \hspace*{20em}
                \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\\{}\end{array}\right\}
                \begin{tabular}{c}Applies Rule 2 of\\Theorem \ref{thm:do-calc-mpdag}\end{tabular}$}}\\
            Remove $X$ from $\mb{X'}$;
        }\Else{
        \Return FAIL\; }
    }\vskip .2cm
    \uIf{$(\, \mb{Y} \perp_{d} \mb{X'} \,\,|\,\, \mb{Z'} \,)_{\, \g_{\overline{\mb{X'}(\mb{Z'})}}}$ where $\mb{X'}(\mb{Z'}) := \mb{X'} \setminus \mathrm{PossAn}(\mb{Z'},\g)$ }{
        \Return $f(\mb{y} \,|\, \mb{z'})$; \hspace*{19.85em}
            \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\end{array}\right\}
            \begin{tabular}{c}Applies Rule 3 of\\Theorem \ref{thm:do-calc-mpdag}\end{tabular}$}}
        \vskip .15cm
    }\Else{
        Let $\mb{Z^D} = \mb{Z'} \cap \mathrm{PossDe}(\mb{X'}, \g)$; \\
        Let $\mb{Z^N} = \mb{Z'} \setminus \mathrm{PossDe}(\mb{X'}, \g)$; \\
        Let $A =$ identification formula for $f(\mb{y},\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}})$; \hspace*{3.6em}
            \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\\{}\\{}\\{}\end{array}\right\}
            \begin{tabular}{c}Applies \\Theorem \ref{thm:id-formula}\end{tabular}$}}\\
        Let $B =$ identification formula for $f(\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}})$; \\
        \Return $\frac{A}{B}$; }
\caption{Conditional Identification for MPDAGs (\texttt{CIDM})}

Let $\g$ be the causal MPDAG in Figure \ref{fig:ex-alg}\subref{fig:ex-alg-a}, and let $\mb{X} = \{X_1,X_2\}$, $\mb{Y} = \{Y\}$, and $\mb{Z} = \{Z\}$. To use Algorithm \ref{alg:cidm}, we first consider the \emph{\texttt{while}} loop of lines \ref{alg:cidm-a}-\ref{alg:cidm-b}. Since there is a possibly causal path from $X_1 \in \mb{X}$ to $\mb{Y} \cup \mb{Z}$ that starts undirected and does not contain $X_2$, we confirm that $\mb{Y} \perp_{d} X_1 \,|\, X_2, \mb{Z}$ in $\g_{\overline{X_2}\underline{X_1}}$. Thus, we define $\mb{X'} = \{X_2\}$ and $\mb{Z'} = \{X_1,Z\}$. Now that all possibly causal paths from $\mb{X'}$ to $\mb{Y} \cup \mb{Z'}$ start directed, we exit the \emph{\texttt{while}} loop. Then we skip lines \ref{alg:cidm-c}-\ref{alg:cidm-d} since $\mb{Y} \not\perp_{d} \mb{X'} \,|\, \mb{Z'}$ in $\g_{\overline{\mb{X'}}}$. Finally, by lines \ref{alg:cidm-e}-\ref{alg:cidm-i},
    \begin{align*}
        f(\mb{y} \,|\, do(\mb{x}), \mb{z}) 
            &= f(y \,|\, do(x_2), x_1, z)\\
            &= f(y \,|\, x_1,x_2,z).
    \end{align*}

Let $\g$ be the causal MPDAG in Figure \ref{fig:ex-alg}\subref{fig:ex-alg-b}, and let $\mb{X} = \{X\}$, $\mb{Y} = \{Y\}$, and $\mb{Z} = \{Z\}$. To use Algorithm \ref{alg:cidm}, we first bypass the \emph{\texttt{while}} loop of lines \ref{alg:cidm-a}-\ref{alg:cidm-b}, since all possibly causal paths from $\mb{X}$ to $\mb{Y} \cup \mb{Z}$ start directed. We also skip lines \ref{alg:cidm-c}-\ref{alg:cidm-d} since $\mb{Y} \not\perp_{d} \mb{X} \,|\, \mb{Z}$ in $\g$. Thus, by lines \ref{alg:cidm-e}-\ref{alg:cidm-i},
    \begin{align*}
        f(\mb{y} \,|\, do(\mb{x}), \mb{z}) 
            = \frac{ \int f(y,z|v_1,x) f(v_1) \mathop{}\!\mathrm{d} v_1 }
              {\int f(z \,|\, v_1 ,x) f(v_1) \mathop{}\!\mathrm{d} v_1}.
    \end{align*}

The proof of Theorem \ref{thm:alg-complete} can be found in Appendix \ref{app:alg}, but we provide an overview here for intuition. We begin the proof by assuming that a possibly causal path---as given in the statement of Theorem \ref{thm:alg-complete}---exists in the MPDAG $\g$. Based on the given d-separation between $X \in \mb{X}$ and $\mb{Y}$, we consider the following non-empty sets:
    \begin{align}
        \mb{S_1} &= \left\{\begin{array}{ll}
                        \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                        \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                    \end{array}\right\}\text{ and} \nonumber\\
        \mb{S_2} &= \{ \text{ paths in $\mb{S_1}$ with the fewest colliders } \}. \end{align}
    The remainder of the proof falls into two cases: (a) when $\mb{S_2}$ only contains paths that start directed (i.e., of the form $X \gets \dots Y$) and (b) when $\mb{S_2}$ contains paths that start undirected (i.e., of the form $X - \dots Y$). Rather than providing an overview of each case, we offer two examples below. Example \ref{ex:alg-condition1} considers an MPDAG with a path that falls into (a), and Example \ref{ex:alg-condition2} considers an MPDAG with a path that falls into (b). In both examples, we show that the conditional causal effect is not identifiable.

\mb{S_1} &= \left\{\begin{array}{ll}
                        \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                        \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                    \end{array}\right\}\text{ and} \nonumber\\
        \mb{S_2} &= \{ \text{ paths in $\mb{S_1}$ with the fewest colliders } \}.

Let $\g=(\mb{V},\mb{E})$ be the MPDAG in Figure \ref{fig:alg-condition2}. If we attempt to identify the conditional effect of $X$ on $Y$ given $Z$, Algorithm \ref{alg:cidm} outputs a \texttt{FAIL}. We want to show this effect is not identifiable in $\g$. To do this, we follow the same strategy as Example \ref{ex:alg-condition1}, and thus, exclude duplicate technical details. However, note that---unlike Example \ref{ex:alg-condition1}---$\g$ contains the path $X - V_1 \to Z \gets Y$, which belongs to the set $\mb{S_2}$ given in \eqref{thm:alg-complete-s2} and which starts undirected.

    Let $\g[D]^1$, $\g[D]^2$ be the DAGs in $[\g]$ with edges $X \to V_1$ and $X \gets V_1$, respectively. Then let $\g[D]^{1'}$, $\g[D]^{2'}$ be the DAGs constructed by removing the edge $X \to Y$ from $\g[D]^1$, $\g[D]^2$, so that 
    \begin{align*}
        \g[D]^{1'}: \,\, &X \to V_1 \to Z \gets Y, \text{ and} \\
        \g[D]^{2'}: \,\, &X \gets V_1 \to Z \gets Y.
    \end{align*}
    Define $\mb{F^*_1}$ (as in Example \ref{ex:alg-condition1}) based on the following SEM with independent errors:
    \begin{align*}
        X   &\gets  \varepsilon_x;                     &\varepsilon_x &\sim \mathcal{N}(0,1);\\
        V_1 &\gets \tfrac{1}{2}X + \varepsilon_{v_1};  &\varepsilon_{v_1} &\sim \mathcal{N}(0,\tfrac{3}{4});\\
        Z   &\gets \tfrac{1}{2} V_1 + \tfrac{1}{2} Y + \varepsilon_z; &\varepsilon_z &\sim \mathcal{N}(0, \tfrac{1}{2});\\
        Y   &\gets \varepsilon_y;                      &\varepsilon_y &\sim \mathcal{N}(0,1).
    \end{align*}
    Analogously, define $\mb{F^*_2}$ based on the following SEM with independent errors:
    \begin{align*}
        X &\gets \tfrac{1}{2}V_1 + \varepsilon_x;        &\varepsilon_x &\sim \mathcal{N}(0,\tfrac{3}{4});\\
        V_1   &\gets  \varepsilon_{v_1};               &\varepsilon_{v_1} &\sim \mathcal{N}(0,1);\\
        Z   &\gets \tfrac{1}{2} V_1 + \tfrac{1}{2} Y + \varepsilon_z; &\varepsilon_z &\sim \mathcal{N}(0, \tfrac{1}{2});\\
        Y   &\gets \varepsilon_y;                      &\varepsilon_y &\sim \mathcal{N}(0,1).
    \end{align*}

    Thus we have two families of interventional densities where $\g[D]^i$ is compatible with $\mb{F^*_i}$ and where we can show $f_1(\mb{v})=f_2(\mb{v})$. To complete the proof, we show that $E[Y \,|\, do(X=1), Z=0]$ is not the same under $f_1$ and $f_2$.
    \begin{align*}
        \mathbb{E}_{f_1}[Y \,|\, do(X=1), Z=0] 
            &\,=\,      \mathbb{E}_{f_1}[Y \,|\, X=1, Z=0] 
             \,=\,      \left. {-\tfrac{2}{15}X} + \tfrac{8}{15}Z \,\right\rvert_{\, X=1, Z=0} 
             \,\neq\,   0.\\
        \mathbb{E}_{f_2}[Y \,|\, do(X=1), Z=0]
            &\,=\,      \mathbb{E}_{f_2}[Y \,|\, Z=0]
             \,=\,      \left. {\tfrac{1}{2}Z} \,\right\rvert_{\, Z=0} 
             \,=\,      0.
    \end{align*}
    The first equality of each line follows from Rules 2 and 3 of \citeauthor{pearl2009causality}'s do calculus (Theorem \ref{thm:do-calc}), respectively, since $Y \perp_{d} X \,|\, Z$ in $\g[D]^{1'}_{\underline{X}}$; $Y \perp_{d} X \,|\, Z$ in $\g[D]^{2'}_{\overline{X}}$; and $f_i$ is consistent with $\g[D]^{i'}$. The remaining equalities follow from properties of multivariate normals (see Lemma \ref{lem:mardia}).

\vspace{.3cm}
    \Input{Disjoint node sets $\mb{X}, \mb{Y}, \mb{Z} \subseteq \mb{V}$ and causal MPDAG $\g=(\mb{V,E})$}
    \Output{Set of possible expressions for $f(\mb{y} \,|\, do(\mb{x}), \mb{z})$, for any $f$ consistent with $\g$}
    \vspace{.3cm}
    \SetAlgoVlined
    Let $\mb{Z'} =  \mb{Z}$ and $\mb{X'} = \mb{X}$;\\ \vskip .2cm
    \While{
    $\exists$ a proper possibly causal path $\mb{X'}$ to $\mb{Y} \cup \mb{Z'}$ in $\g$ that starts undirected}{
        Pick $X \in \mb{X'}$ on such a path;\\
        \uIf{
        $(\, \mb{Y} \perp_{d} X \,\,|\,\, \mb{X'} \setminus \{X\}, \mb{Z'} \,)_{\, \g_{\overline{\mb{X'} \setminus \{X\}} \underline{X}}}$}{
            Add $X$ to $\mb{Z'}$;\\
            Remove $X$ from $\mb{X'}$;
        }\Else{
        Pick a shortest proper possibly causal path in $\g$ \\
            \hspace*{.4em} from  $\mb{X'}$ to $\mb{Y} \cup \mb{Z'}$
             that starts with $X - V_2$;
            \hspace*{25.4em}
            \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\\{}\\{}\\{}\end{array}\right\}
            \begin{tabular}{c}Partitions $[\g]$ \\by orienting $X - V_2$
            \end{tabular}$}}\\
            \vspace{-.5cm}
        Form $\g_1$: orient $X \to V_2$, complete R1-R4 of \cite{meek1995causal}; \\
        Form $\g_2$: orient $X \gets V_2$, complete R1-R4 of \cite{meek1995causal}; \\
        \Return \texttt{CIDME}($\mb{X',Z',Y}, \g_1$); \\
        \Return \texttt{CIDME}($\mb{X',Z',Y}, \g_2$); }
    }\vskip .2cm
    \uIf{$(\, \mb{Y} \perp_{d} \mb{X'} \,\,|\,\, \mb{Z'} \,)_{\, \g_{\overline{\mb{X'}(\mb{Z'})}}}$ where $\mb{X'}(\mb{Z'}) := \mb{X'} \setminus \mathrm{PossAn}(\mb{Z'},\g)$}{
        \Return $f(\mb{y} \,|\, \mb{z'})$;
        \vskip .15cm
    }\Else{
        Let $\mb{Z^D} = \mb{Z'} \cap \mathrm{PossDe}(\mb{X'}, \g)$;\\
        Let $\mb{Z^N} = \mb{Z'} \setminus \mathrm{PossDe}(\mb{X'}, \g)$;\\
        Let $A =$ identification formula for $f(\mb{y},\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}})$;\\
        Let $B =$ identification formula for $f(\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}})$;\\
        \Return $\frac{A}{B}$;
    }
\caption{Conditional Identification for MPDAGs + Enumeration (\texttt{CIDME})}

{\normalfont (\textbf{Rules of the do Calculus}; Theorem 3.4.1 of \cite{pearl2009causality})}
Let $\mb{X,Y,Z,}$ and $\mb{W}$ be pairwise disjoint (possibly empty) node sets in a causal DAG $\g[D]$. Let $\g[D]_{\overline{\mb{X}}}$ denote the graph obtained by deleting all edges into $\mb{X}$ from $\g[D]$. Similarly, let $\g[D]_{\underline{\mb{X}}}$ denote the graph obtained by deleting all edges out of $\mb{X}$ in $\g[D]$, and let $\g[D]_{\overline{\mb{X}}\underline{\mb{Z}}}$ denote the graph obtained by deleting all edges into $\mb{X}$ and all edges out of $\mb{Z}$ in $\g[D]$. The following rules hold for all densities consistent with $\g[D]$.

\textbf{Rule 1.} If $(\mb{Y} \perp_{d} \mb{Z} \given \mb{X}, \mb{W})_{\g[D]_{\overline{\mb{X}}}}$, then
    \begin{align}
        f(\mb{y} | do(\mb{x}), \mb{z,w}) = f(\mb{y} | do(\mb{x}), \mb{w}). \end{align}

\textbf{Rule 2.} If $(\mb{Y} \perp_{d} \mb{X} \given \mb{Z}, \mb{W})_{\g[D]_{\underline{\mb{X}}\overline{\mb{W}}}}$, then
    \begin{align}
        f(\mb{y} | do(\mb{x}),\mb{z},do(\mb{w})) = f(\mb{y} | \mb{x},\mb{z},do(\mb{w})). \end{align}

\textbf{Rule 3.} If $(\mb{Y} \perp_{d} \mb{X} \given \mb{Z}, \mb{W})_{\g[D]_{\overline{\mb{W}}, \overline{\mb{X}(\mb{Z})}}}$, then
    \begin{align}
        \begin{split}
            f(\mb{y} | do(\mb{x}), \mb{z}, do(\mb{w})) = f(\mb{y} | \mb{z}, do(\mb{w})), \end{split}
    \end{align}
where $\mb{X(Z)} := \mb{X} \setminus \mathrm{An}(\mb{Z}, \g[D]_{\overline{\mb{W}}})$.

conclusions:
The following rules hold for all densities consistent with $\g[D]$.

\textbf{Rule 1.} If $(\mb{Y} \perp_{d} \mb{Z} \given \mb{X}, \mb{W})_{\g[D]_{\overline{\mb{X}}}}$, then
    \begin{align}
        f(\mb{y} | do(\mb{x}), \mb{z,w}) = f(\mb{y} | do(\mb{x}), \mb{w}). \label{thm:do-rule1}
    \end{align}

\textbf{Rule 2.} If $(\mb{Y} \perp_{d} \mb{X} \given \mb{Z}, \mb{W})_{\g[D]_{\underline{\mb{X}}\overline{\mb{W}}}}$, then
    \begin{align}
        f(\mb{y} | do(\mb{x}),\mb{z},do(\mb{w})) = f(\mb{y} | \mb{x},\mb{z},do(\mb{w})). \label{thm:do-rule2}
    \end{align}

\textbf{Rule 3.} If $(\mb{Y} \perp_{d} \mb{X} \given \mb{Z}, \mb{W})_{\g[D]_{\overline{\mb{W}}, \overline{\mb{X}(\mb{Z})}}}$, then
    \begin{align}
        \begin{split}
            f(\mb{y} | do(\mb{x}), \mb{z}, do(\mb{w})) = f(\mb{y} | \mb{z}, do(\mb{w})), \label{thm:do-rule3}
        \end{split}
    \end{align}
where $\mb{X(Z)} := \mb{X} \setminus \mathrm{An}(\mb{Z}, \g[D]_{\overline{\mb{W}}})$

