{\normalfont (Theorem 3.2.4 of \citealp{mardia1980multivariate})}
    Let $\mb{X} = (\mb{X_1}^T, \mb{X_2}^T)^T$ be a $p$-dimensional multivariate Gaussian random vector with mean vector $\mb{\mu} = (\mb{\mu_1}^T, \mb{\mu_2}^T)^T$ and covariance matrix $\mb{\Sigma} = \begin{bmatrix}
    \mb{\Sigma_{11}} & \mb{\Sigma}_{12} \\
    \mb{\Sigma_{21}} & \mb{\Sigma}_{22}
    \end{bmatrix}$, so that $\mb{X_1}$ is a $q$-dimensional multivariate Gaussian random vector with mean vector $\mb{\mu_1}$ and covariance matrix $\mb{\Sigma_{11}}$ and $\mb{X_2}$ is a $(p-q)$-dimensional multivariate Gaussian random vector with mean vector $\mb{\mu_2}$ and covariance matrix $\mb{\Sigma_{22}}$. Then $E[\mb{X_2}|\mb{X_1} = \mb{x_1}] = \mb{\mu_2} + \mb{\Sigma_{21}} \mb{\Sigma_{11}}^{-1}(\mb{x_1} - \mb{\mu_1})$.

{
ormalfont (	extbf{Wright's Rule}; \citealp{wright1921correlation, wright1934method})}
    Consider the following structural equation model (SEM) over a vector of random variables $\mb{X} = (X_1, \dots, X_k)^T$. The set of equations is given by $\mb{X}=\mb{AX}+\mb{\varepsilon}$, where $\mb{A} \in \mathbb{R}^{k 	imes k}$ is a matrix with zeroes on the diagonal and coefficients from the SEM on the off-diagonals, $\mb{\varepsilon} = (\varepsilon_1, \dots, \varepsilon_k)^T$ is a vector of mutually independent errors with finite means, and $Var(X_i) = 1$ for all $i \in \{1, \dots, k\}$. Let $\g[D]$ be a DAG over $\mb{X}$ such that $X_i 	o X_j$ is in $\g[D]$ if and only if $A_{ji} 
eq 0$ for $i, j \in \{1, \dots, k\}$, $i 
eq j$. (We call $A_{ji}$ the edge coefficient of $X_i 	o X_j$ when $A_{ji} 
eq 0$.) Further, let $\{p_1, \dots, p_s\}$ be the set of paths between $X_i$ and $X_j$ in $\g[D]$ that do not contain a collider, and let $\pi_r$ be the product of all edge coefficients along the path $p_r$, $r \in \{1, \dots, s\}$. Then $\mathrm{Cov}(X_i, X_j) = \sum_{r=1}^s \pi_r$.

{\normalfont (cf. proof of Lemma B.4, \cite{henckel2022graphical})}
    Consider the following structural equation model (SEM) over a vector of random variables $\mb{X} = (X_1, \dots, X_k)^T$. The set of equations is given by $\mb{X}=\mb{AX}+\mb{\varepsilon}$, where $\mb{A} \in \mathbb{R}^{k \times k}$ is a matrix with zeroes on the diagonal and coefficients from the SEM on the off-diagonals, $\mb{\varepsilon} = (\varepsilon_1, \dots, \varepsilon_k)^T$ is a vector of mutually independent errors with finite means, and finite variances. Let $\g[D]$ be a DAG over $\mb{X}$ such that $X_i \to X_j$ is in $\g[D]$ if and only if $A_{ji} \neq 0$ for $i, j \in \{1, \dots, k\}$, $i \neq j$. (We call $A_{ji}$ the edge coefficient of $X_i \to X_j$ when $A_{ji} \neq 0$.) Then we can write
    \begin{align*}
        X_i             &\,\,=\,\,  \mspace{-50mu} \sum_{ \mspace{40mu} j: \, X_j \in \mathrm{An}(X_i, \g[D])} \mspace{-45mu} \tau_{ji} \varepsilon_j 
        \intertext{where we define $\tau_{ji}$ as follows. Let $\tau_{ii} = 1$. For the remaining $\tau_{ji}$, consider the set of all causal paths $\{p_1, \dots, p_s\}$ from  $X_j$ to $X_i$ in $\g[D]$, and let $\pi_r$ be the product of all edge coefficients along the path $p_r$, $r \in \{1, \dots, s\}$. Then let $\tau_{ji} = \sum_{r=1}^s \pi_r$. Further, we have}
        \mathrm{Cov}(X_i,X_j)   &\,\,=\,\,  \mspace{-120mu} \sum_{ \mspace{120mu} k: \, X_k \in \mathrm{An}(X_i, \g[D]) \, \cap\, \mathrm{An}(X_j, \g[D])} \mspace{-115mu} \tau_{ki} \tau_{kj} \mathrm{Var}(\varepsilon_k),
    \end{align*}

{\normalfont (cf. Theorem 1 and Proposition 3 of \citealp{lauritzen1990independence})}
    Let $\g[D] = (\mb{V},\mb{E})$ be a DAG, and let $f$ be an observational density over $\mb{V}$. Then $f$ is Markov compatible with $\g[D]$ if and only if 
    \begin{align*}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]) \cup \mathrm{Pa}(V_i,\g[D]) \big) \Big] | \mathrm{Pa}(V_i, \g[D])
    \end{align*}
    for all $V_i \in \mb{V}$, where $\perp\!\!\!\!\perp$ indicates independence with respect to $f$.

conclusions:
$f$ is Markov compatible with $\g[D]$ if and only if 
    \begin{align*}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]) \cup \mathrm{Pa}(V_i,\g[D]) \big) \Big] | \mathrm{Pa}(V_i, \g[D])
    \end{align*}
    for all $V_i \in \mb{V}$, where $\perp\!\!\!\!\perp$ indicates independence with respect to $f$

