    Finally, to see that $\mb{N} \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$, let $N$ be an arbitrary node in $\mb{N} \setminus \mb{N'} = \mb{X_{n_i}} \cap \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}})$. This implies that there is a causal path in $\g[D]_{\overline{\mb{X_{p_i}}}}$ from $N$ to some $P_i \in \mb{P_i} \subseteq \mathrm{Pa}(\mb{B_i},\g)$. This path is also in $\g[D]$, and thus by Lemma \ref{lem:pc-imply1b}, its corresponding path in $\g$ is possibly causal from $N$ to $\mathrm{Pa}(\mb{B_i},\g)$. Therefore by Lemma \ref{lem:concat}, there is a possibly causal path in $\g$ from $N$ to $\mb{B_i}$. Since $\mb{B_i} \subseteq \mb{C_n}$, then $N \notin \cup_{j=n+1}^{k} \mb{C_j}$ by Lemma \ref{lem:bucket-restrict2}. Further, since $N \in \mb{X}$ and $\mb{B_i} \subseteq \mb{D}$, then $N \notin \mb{C_n}$ by Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e}.

    \vskip .1in

    \eqref{eq:algo-4-one-6}
    Let $\mb{N} = \emptyset$, $\mb{H} = \mb{X_{p_i}}$, $\mb{X'} = \emptyset$, and $\mb{N'} = \emptyset$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{H}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{H} \subseteq \mb{X_{p_i}}$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. Finally, note that $\mb{N} \setminus \mb{N'} = \emptyset \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$.


