Suppose that $f(\mb{v} | do(\mb{x}))$ is consistent with $\g[D]^*$. Then by definition, there exists a set of interventional densities $\mb{F^*}$ such that $\g[D]^*$ is compatible with $\mb{F^*}$. Let $f(\mb{v})$ be the density in $\mb{F^*}$ under a null intervention. Note that by the truncated factorization in Equation \eqref{eq:trunc-fact}, $f(\mb{v})$ is Markov compatible with $\g[D]^*$. Thus by Lemma \ref{lem:markov-equiv},
    \begin{align}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]^*) \cup \mathrm{Pa}(V_i,\g[D]^*) \big) \Big] | \mathrm{Pa}(V_i, \g[D]^*) \end{align}
    for all $V_i \in \mb{V}$, where $\perp\!\!\!\!\perp$ indicates independence with respect to $f(\mb{v})$. Further, since $\mathrm{De}(V_i,\g[D]^*) \subseteq \mathrm{De}(V_i,\g[D])$, then $\mathrm{De}(V_i,\g[D]^*) \cap \mathrm{Pa}(V_i,\g[D]) = \emptyset$ and thus $\mathrm{Pa}(V_i,\g[D]) \subseteq \mb{V} \setminus \mathrm{De}(V_i, \g[D]^*)$. Therefore it follows from \eqref{eq:markov-sub-1} that
    \begin{align} 
        V_i \perp\!\!\!\!\perp \Big[ \mathrm{Pa}(V_i,\g[D]) \setminus \mathrm{Pa}(V_i,\g[D]^*) \Big] \,\, \Big| \,\, \mathrm{Pa}(V_i,\g[D]^*). \end{align}

    Let $f(\mb{v} | do(\mb{x'}))$, $\mb{X'} \subseteq \mb{V}$, be an arbitrary density in $\mb{F^*}$. Then by definition and \eqref{eq:markov-sub-2}
    \begin{align*}
        f(\mb{v} | do(\mb{x'})) &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D]^*)) \mathbbm{1}(\mb{X'} = \mb{x'})\\
                                &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D])) \mathbbm{1}(\mb{X'} = \mb{x'}).
    \end{align*}
    Since $f(\mb{v} | do(\mb{x'}))$ was arbitrary, this holds for all densities in $\mb{F^*}$. Thus, $\g[D]$ is compatible with $\mb{F^*}$. Since $f(\mb{v} | do(\mb{x})) \in \mb{F^*}$, then by definition, it is consistent with $\g[D]$.

{\normalfont (cf. Lemma 1 of \cite{zhang2006causal})}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{W}$ be pairwise disjoint node sets in a DAG $\g[D]=(\mb{V,E})$, and let $\g$ be an MPDAG such that $\g[D] \in [\g]$. Additionally, let $p$ be a path in $\g[D]$ from $\mb{Z}$ to $\mb{Y}$ such that $p$ is d-connecting given $\mb{X} \cup \mb{W}$ but no subsequence of $p$ in $\g[D]$ is d-connecting given $\mb{X} \cup \mb{W}$. Then the following hold.
    \begin{enumerate}[label=(\roman*)]
        \item All colliders on $p$ are unshielded.

        \item The path in $\g$ corresponding to $p$ is of definite status.
    \end{enumerate}

Suppose there is a path in $\g = (\mb{V, E})$ from $X \in \mb{X}$ to $\mb{Y} \cup \mb{Z}$ that does not contain $\mb{X} \setminus \{X\}$, is possibly causal, starts undirected---and where $\mb{Y} \not\perp_{d} X \,|\, \mb{X} \setminus \{X\}, \mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. We want to show that the conditional effect of $\mb{X}$ on $\mb{Y}$ given $\mb{Z}$ is not identifiable in $\g$. Since ${\mb{Y} \not\perp_{d} X \,|\, \mb{X} \setminus \{X\}, \mb{Z}}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$, the following sets must be non-empty:
    \begin{align*}
        \mb{S_1} &= \left\{\begin{array}{ll}
                        \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                        \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                    \end{array}\right\} \text{ and}\\
        \mb{S_2} &= \hspace{.05in}\{ \hspace{.05in}\text{paths in $\mb{S_1}$ with the fewest colliders} \hspace{.05in}\}.
    \end{align*}
    Then consider the following set:
    \begin{align*}
        \mb{S_3} &= \hspace{.05in}\{ \hspace{.05in}\text{paths in } \mb{S_2} \text{ that start undirected}\hspace{.05in}\}. \hspace{1.8in}
    \end{align*}
    We divide the remainder of the proof into two cases based on whether $\mb{S_3} = \emptyset$. In both cases, we consider DAGs $\g[D]^1, \g[D]^2 \in [\g]$ with paths in the sets above. To show the conditional effect is not identifiable in $\g$, it suffices to show that each $\g[D]^i$ is compatible with a family of interventional densities $\mb{F^*_i} = \{ f_i(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ such that the following hold.
    \begin{align}
        f_1(\mb{v}) &\,=\, f_2(\mb{v}). \\
        f_1(\mb{y} \,|\, do(\mb{x}), \mb{z}) & \,\neq\, f_2(\mb{y} \,|\, do(\mb{x}), \mb{z}). \end{align}

    Before proceeding to cases, we briefly show that all paths in $\mb{S_1}$ are proper paths from $\mb{X}$ to $\mb{Y}$ that are open given $\mb{Z}$. To see this, note that since every path in $\mb{S_1}$ is of definite status and open given $\mb{X} \setminus \{X\} \cup \mb{Z}$, it cannot have definite non-colliders in $\mb{X} \setminus \{X\} \cup \mb{Z}$. Further, since there are no edges into $\mb{X} \setminus \{X\}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$, all of the colliders on any path in $\mb{S_1}$ cannot be in $\mb{X} \setminus \{X\}$ and must have descendants in $\mb{Z}$.


    \vskip .2in


    \noindent
    \textbf{CASE 1:}
    Consider when $\mb{S_3} \neq \emptyset$, and define the following sets.
    \begin{align*}
        \mb{S_4} &= \{ \text{paths in $\mb{S_3}$ with the fewest edges} \}.\\
        \mb{S_5} &= \{ \text{paths in $\mb{S_4}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.
    \end{align*}
    Pick an arbitrary path $\overline{p} := \langle X = P_1, \dots, P_k = Y \rangle$, $k > 1$, $Y \in \mb{Y}$, in $\mb{S_5} \subseteq \mb{S_1}$. Note that the sequence of nodes in $\g$ corresponding to $\overline{p}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ forms a path $p$ in $\g$ that contains the same edge orientations as $\overline{p}$. Then note that since $\overline{p} \in \mb{S_1}$, we have shown that $\overline{p}$---and therefore $p$---is a proper path from $\mb{X}$ to $\mb{Y}$. Further, both paths start undirected, since $\overline{p} \in \mb{S_3}$.

    Consider first when $p$ is possibly causal so that $p$---and therefore $\overline{p}$---has no colliders. Since $\overline{p} \in \mb{S_1}$ is of definite status and we have shown that paths in $\mb{S_1}$ are open given $\mb{Z}$, then $\overline{p}$---and therefore $p$---does not contain nodes in $\mb{Z}$. Thus, $p$ is a proper, possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ that starts undirected and does not contain nodes in $\mb{Z}$. It follows by Proposition \ref{prop:id-necessary} that the conditional effect of $\mb{X}$ on $\mb{Y}$ given $\mb{Z}$ is not identifiable in $\g$, and we are done.

    Hence, we consider when $p$ is not possibly causal for the remainder of this case. For sake of contradiction, suppose $\overline{p}$ does not contain colliders. Since $\overline{p}$ is of definite status and starts undirected, then $\overline{p}$---and therefore $p$---cannot contain an edge $P_i \gets P_{i+1}$, $i \in \{1, \dots, k-1\}$. Thus by Lemma \ref{lem:pc-def-stat}, $p$ is not of definite status. The only way for $\overline{p}$ to be of definite status while $p$ is not is for the paths to contain at least one subpath $P_i - P_{i+1} - P_{i+2}$ that is unshielded in $\overline{p}$ but shielded in $p$. This forces $i=1$, since $\overline{p}$ is a proper path in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. That is, $\overline{p}$ begins $X - P_2 - P_3$ and $\g$ contains $X \to P_3$. It follows that $p(P_2, P_k)$ is of definite status. Since $p$---and therefore $p(P_2, P_k)$---does not contain an edge $P_i \gets P_{i+1}$, then by Lemma \ref{lem:pc-def-stat}, $p(P_2, P_k)$ is possibly causal. However, $p$ is not possibly causal, so $\g$ must contain an edge $X \gets P_j$, $j \in \{4, \dots, k\}$, so that $\g$ contains $P_3 \gets X \gets P_j$. But this contradicts that $p(P_2, P_k)$ is possibly causal (Lemma \ref{lem:nobackpaths}).

    Thus, $\overline{p}$ has at least one collider. Let $\mb{C} = \{C_1, \dots, C_m \}$, $1 \le m \le k-3$, be the set of all colliders on $\overline{p}$ in order of their appearance on $\overline{p}$. Since we have shown that paths in $\mb{S_1}$ are open given $\mb{Z}$, every collider in $\mb{C}$ is in $\mathrm{An}(\mb{Z},\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}})$. Then for each $i \in \{1, \dots, m\}$, let $\overline{q_i} = \langle C_i = Q_{i_1}, \dots, Q_{i_{k_i}}=Z_i \rangle$ be a shortest causal path from $C_i \in \mb{C}$ to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$.

    Using these paths, we turn to the task of finding DAGs in $[\g]$ that are compatible with families of interventional densities such that \eqref{thm:alg-complete-1}-\eqref{thm:alg-complete-2} hold. To do this, we consider the subcases below.
    \begin{itemize}
        \item \textbf{SUBCASE 1:}
        Let $p$ be of definite status. Consider any two DAGs $\g[D]^1, \g[D]^2 \in [\g]$ that include the edges $X \to P_2$ and $X \gets P_2$, respectively. Then construct $\g[D]^{1'}$ and $\g[D]^{2'}$ by removing every edge from $\g[D]^1$ and $\g[D]^2$ other than those on paths corresponding to $\overline{p}$ and $\overline{q_1}, \dots, \overline{q_m}$. Since $p$ is of definite status, note that the paths in $\g[D]^{1'}$ and $\g[D]^{2'}$ corresponding to $p$ begin $X \to P_2 \to \dots \to C_1$, and $X \gets P_2 \dots C_1$, respectively.

        \item \textbf{SUBCASE 2:}
        Let $p$ be of non-definite status. As before, this forces $\overline{p}$ to begin $X - P_2 - P_3$; $\g$ to contain $X \to P_3$; and $P_2$ to be the only node on $p$ not of definite status. To choose DAGs in $[\g]$, we first restrict the class. Thus, construct the MPDAG $\g^*$ by adding $P_2 \to P_3$ to $\g$ and completing \citeauthor{meek1995causal}'s (\citeyear{meek1995causal}) orientation rules. Note that by Lemma \ref{lem:adding-edges-imply}, $\g^*$ contains $X - P_2$. Now consider any two DAGs $\g[D]^1, \g[D]^2 \in [\g^*] \subseteq [\g]$ that include the edges $X \to P_2$ and $X \gets P_2$, respectively. And construct $\g[D]^{1'}$ and $\g[D]^{2'}$ by removing every edge from $\g[D]^1$ and $\g[D]^2$ other than those on paths corresponding to $\overline{p}$ and $\overline{q_1}, \dots, \overline{q_m}$. Note that the paths in $\g[D]^{1'}$ and $\g[D]^{2'}$ corresponding to $p$ begin $X \to P_2 \to \dots \to C_1$, and $X \gets P_2 \to \dots \to C_1$, respectively.
    \end{itemize}

    Now that we have chosen $\g[D]^1, \g[D]^2 \in [\g]$, we construct a family of interventional densities $\mb{F^*_i} = \{ f_i(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ compatible with each DAG. Start by considering the following linear structural equation model (SEM). Each random variable $V_i \in \mb{V}$ is a linear combination of its parents in $\g[D]^{1'}$ and $\varepsilon_{v_i} \sim N(0, \sigma^2_{v_i})$, where $\mb{\sigma}^2_{v_i} \in (0,1]$ and $\{\mb{\varepsilon}_{v_i}: V_i \in \mb{V}\}$ are mutually independent:
    \begin{align} V_i \ \longleftarrow \mspace{-25mu} \sum_{V_j \in \mathrm{Pa}(V_i, \g[D]^{1'})} \mspace{-25mu} A_{ij} V_j + \varepsilon_{v_i}.
    \end{align}
    Each coefficient $A_{ij}$ in this linear combination is defined by the edge coefficient of each $V_i \gets V_j$ in $\g[D]^{1'}$. We pick these edge coefficients in conjunction with $\{\mb{\sigma}^2_{v_i}: V_i \in \mb{V}\}$ in such a way that each $A_{ij} \in (0,1)$ and $\mathrm{Var}(V_i)=1$. 

    We build $\mb{F^*_1}$ by letting $f_1(\mb{v})$ be the density of the multivariate normal generated by the SEM in \eqref{thm:alg-complete-3}. For the remaining densities in $\mb{F^*_1}$, we let $f_1(\mb{v} \,|\, do(\mb{x'})) := f_*(\mb{v})$, where $f_*$ is  the density of the multivariate normal generated by taking the SEM in \eqref{thm:alg-complete-3} and replacing $\mb{X'}$ with its interventional value $\mb{x'}$ \citep{pearl2009causality}. Note that $\g[D]^{1'}$ is compatible with $\mb{F^*_1}$ by construction---and therefore, so is $\g[D]^1$ (Lemma \ref{lem:markov-sub}).

    To construct $\mb{F^*_2}$, define a linear SEM identical to the SEM in \eqref{thm:alg-complete-3} but based on the parents in $\g[D]^{2'}$. Let $f_2(\mb{v})$ be the density of the resulting distribution, which is another multivariate normal with mean vector zero and a covariance matrix with ones on the diagonal. We show below that the off-diagonal entries---which house the variables' covariances---are identical to the covariances from the SEM in \eqref{thm:alg-complete-3}. Thus, in an analogous way to $\mb{F^*_1}$, we can define $\mb{F^*_2} = \{ f_2(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ such that $\g[D]^{2'}$---and therefore $\g[D]^2$---is compatible with $\mb{F^*_2}$ and such that $f_2(\mb{v}) = f_1(\mb{v})$.

    To see that the covariances are identical, note that by Lemma \ref{lem:wright}, the covariances based on $\g[D]' \in \{ \g[D]^{1'}, \g[D]^{2'} \}$ will equal the product of edge coefficients along non-collider paths in $\g[D]'$. Since $\g[D]^{1'}$ and $\g[D]^{2'}$ have identical adjacencies, we only need to show that these DAGs have an identical set of colliders. Let $q'_1, \dots, q'_m$, and $p'$ be the paths in $\g[D]'$ corresponding to $\overline{p}$ and $\overline{q_1}, \dots, \overline{q_m}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. Recall that $\mb{C}$ is the set of all colliders on $\overline{p}$. Then note that $\mb{C}$ is also the set of all colliders on $p'$, since $P_1, P_3, \dots, P_k$ are nodes of definite status on $p$ in $\g$ and since $P_2$ is always a non-collider on $p'$. Further, by Lemma \ref{lem:collider-paths}, $C_i$ is the only node on both $p'$ and $q_i'$, $i \in \{1, \dots, m\}$, and there is no shared node between the causal paths $q_i'$ and $q_j'$, $i \neq j$. Therefore, $\mb{C}$ is the set of all colliders on any path in either $\g[D]^{1'}$ or $\g[D]^{2'}$.

    Thus we have two families of interventional densities such that $\g[D]^i$ is compatible with $\mb{F^*_i}$ and such that $f_1(\mb{v})=f_2(\mb{v})$ so that \eqref{thm:alg-complete-1} holds. To complete Case 1, we show that \eqref{thm:alg-complete-2} holds. It suffices to show that $E[Y \,|\, do(\mb{X}=\mb{1}), \mb{Z}=\mb{0}]$ is not the same under $f_1$ and $f_2$. We start by calculating this expectation under $f_2$:
    \begin{align*}
        \mathbb{E}_{f_2}[Y \,|\, do(&\mb{X}=\mb{1}), \mb{Z} = \mb{0}]\\
            &\,=\, \left. \mathbb{E}_{f_2}[Y \,|\, Z_1, \dots, Z_m] \,\, \right\rvert_{\, \mb{Z}=\mb{0}}\\
            &\,=\, \left. \begin{bmatrix}
                                \mathrm{Cov}_{f_2}(Y, Z_1) \,\, \cdots \,\, \mathrm{Cov}_{f_2}(Y, Z_m) 
                          \end{bmatrix}
                          \, \mb{\Sigma}^{-1}
                          \,\, \mb{Z} \,\, \right\rvert_{\, \mb{Z}=\mb{0}}\\
            &\,=\, 0,
    \end{align*}
    where $\mb{\Sigma}$ is the covariance matrix of $\mb{Z}$ under $f_2$ (and where $\mb{\Sigma}$ is invertible since $\mb{V}$ is non-degenerate). The first equality follows from Rule 3 of Pearl's do calculus (Theorem \ref{thm:do-calc}), since $Y \perp_{d} \mb{X} \,|\, \mb{Z}$ in $\g[D]^{2'}_{\overline{\mb{X}}}$ and since $f_2$ is consistent with $\g[D]^{2'}$. The second equality follows from properties of multivariate normals (see Lemma \ref{lem:mardia}).

    Next, we calculate the same expectation under $f_1$:
    \begin{align*}
        \mathbb{E}_{f_1}[Y \,|\, do(&\mb{X}= \mb{1}), \mb{Z} = \mb{0}]\\
            &\,=\, \left. \mathbb{E}_{f_1}[Y \,|\, X, Z_1, \dots, Z_m] \,\, \right\rvert_{\, X=1, \, \mb{Z}=\mb{0}}\\
            &\,=\, \left. \begin{bmatrix}
                                \mathrm{Cov}_{f_1}(Y, X) & \mathrm{Cov}_{f_1}(Y,Z_1) \,\, \cdots \,\, \mathrm{Cov}_{f_1}(Y, Z_m) 
                          \end{bmatrix} \,
                          \mb{\Sigma}^{-1} \,\, 
                          \begin{bmatrix}
                                X \\
                                \mathbf{Z}
                          \end{bmatrix} \,\, \right\rvert_{\, X=1, \, \mb{Z}=\mb{0}}\\
            &\,=\, \begin{bmatrix}
                                0 \,\, \cdots \,\, 0 & \mathrm{Cov}_{f_1}(Y, Z_m) 
                          \end{bmatrix} \,
                          \mb{\Sigma}_1^{-1} \,\, 
                          \begin{bmatrix}
                                1 \\
                                \mathbf{0}
                          \end{bmatrix}\\
            &\,=\, \Sigma_{m+1,1} \cdot \mathrm{Cov}_{f_1}(Y, Z_m) \,\,,
    \end{align*} 
    where $\mb{\Sigma}$ is the invertible covariance matrix of $(X, Z_1, \dots, Z_m)^T$ under $f_1$ and where $\Sigma_{m+1,1}$ is the $(m+1,1)^{th}$ entry of $\mb{\Sigma}^{-1}$. The first equality follows from Rules 3 and 2 of Pearl's do calculus (Theorem \ref{thm:do-calc}), since $Y \perp_{d} \mb{X} \setminus \{X\} \,|\, X, \mb{Z}$ in $\g[D]^{1'}_{\overline{\mb{X}}}$, since $Y \perp_{d} X \,|\, \mb{Z}$ in $\g[D]^{1'}_{\underline{X}}$, and since $f_1$ is consistent with $\g[D]^{1'}$. The second equality follows from properties of multivariate normals (see Lemma \ref{lem:mardia}), and the third follows from applying Wright's Rule (Lemma \ref{lem:wright}) to $\g[D]^{1'}$.

    To complete Case 1, we show this expectation is non-zero so that \eqref{thm:alg-complete-2} holds. Note that $\mathrm{Cov}_{f_1}(Y, Z_m) \neq 0$, since by Lemma \ref{lem:wright}, it equals the product of all edge coefficients on $-(q'_m) \oplus p'(C_m,Y)$ in $\g[D]^{1'}$, which were chosen to be in $(0,1)$. To show that $\Sigma_{m+1,1} \neq 0$, we find the following.
    \begin{align*}
    \mb{\Sigma} \,=\, &
    \begin{blockarray}{ccccc}
        \begin{block}{[ccccc]}
          1                 & \mathrm{Cov}_{f_1}(X,Z_1)   &        &   & \makebox(0,0){\text{\huge0}} \\
          \mathrm{Cov}_{f_1}(X,Z_1) & 1                   & \ddots &   & \\
      	                    & \mathrm{Cov}_{f_1}(Z_1,Z_2) & \ddots &   & \\
          \makebox(0,0){\text{\huge0}}          &	                    & \ddots & 1 & \mathrm{Cov}_{f_1}(Z_{m-1}, Z_m) \\
                            &	                  &        & \mathrm{Cov}_{f_1}(Z_{m-1}, Z_m) & 1\\
        \end{block}
    \end{blockarray}.\\
        \Sigma_{m+1,1} &\,=\, \frac{\,\, (-1)^{m+2} \,\,}{\mathrm{Det}(\mb{\Sigma})} \cdot \mathrm{Cov}_{f_1}(X,Z_1) \cdot \mathrm{Cov}_{f_1}(Z_1,Z_2) \,\cdots\, \mathrm{Cov}_{f_1}(Z_{m-1},Z_{m}) \\
                  &\,\neq\, 0.
    \end{align*}
    The final equality follows by applying Wright's Rule (Lemma \ref{lem:wright}) to $\g[D]^{1'}$ and noting that the paths between $X$ and $Z_1$ as well as $Z_i$ and $Z_{i+1}$, $i \in \{1, \dots, m-1\}$, have edge coefficients in $(0,1)$ and no colliders.


    \vskip .2in


    \noindent
    \textbf{CASE 2:}
    Consider when $\mb{S_3} = \emptyset$, and define the following sets.
    \begin{align*}
        \mb{S_6} &= \{ \text{paths in $\mb{S_2}$ with the fewest edges} \}.\\
        \mb{S_7} &= \{ \text{paths in $\mb{S_6}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.
    \end{align*}
    Pick an arbitrary path $\overline{p} := \langle X = P_1, \dots, P_k = Y \rangle$, $k > 1$, $Y \in \mb{Y}$, in $\mb{S_7}$. Note that $\overline{p}$ begins $X \gets P_2$, since $\overline{p} \in \mb{S_2}$ is a path in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ and $\mb{S_3} = \emptyset$. Further, $\overline{p}$ is a proper path from $\mb{X}$ to $\mb{Y}$ that is open given $\mb{Z}$, since we have shown this holds for all paths in $\mb{S_1}$. Let $\mb{C} = \{C_1, \dots, C_m \}$, $1 \le m \le k-3$, be the set of all colliders on $\overline{p}$ in order of their appearance on $\overline{p}$, where possibly $\mb{C} = \emptyset$. Note that every node in $\mb{C}$ is in $\mathrm{An}(\mb{Z},\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}})$, since $\overline{p}$ is open given $\mb{Z}$. Then let $\overline{q_i} = \langle Q_{i_1}, \dots, Q_{i_{k_i}} \rangle$, $i \in \{1, \dots m\}$, be a shortest causal path from $C_i$ to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. Let $p$, $q_1, \dots, q_m$ be the paths in $\g$ corresponding to $\overline{p}$, $\overline{q_1}, \dots, \overline{q_m}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$.

    Next, recall from the beginning of the proof that there is a path in $\g$ from $X$ to $\mb{Y} \cup \mb{Z}$ that does not contain $\mb{X} \setminus \{X\}$, is possibly causal, and starts undirected. Let $r = \langle X = R_1, \dots, R_n \rangle, n >1$, be a shortest such path. When $r$ ends in $\mb{Y}$, it is a proper, possibly causal path from $\mb{X}$ to $\mb{Y}$ that starts undirected and does not contain nodes in $\mb{Z}$. It follows by Proposition \ref{prop:id-necessary} that the conditional effect of $\mb{X}$ on $\mb{Y}$ given $\mb{Z}$ is not identifiable in $\g$, and we are done. Hence, suppose $r$ ends in $\mb{Z}$ for the remainder of this proof.

    Using these paths, we turn to the task of finding DAGs in $[\g]$ that are compatible with families of interventional densities such that \eqref{thm:alg-complete-1}-\eqref{thm:alg-complete-2} hold. We start by considering a restriction of the class $[\g]$ using an MPDAG $\g^*$. When $X \notin \mathrm{Adj}(R_3, \g)$, then let $\g^* = \g$. When $X \in \mathrm{Adj}(R_3, \g)$, note that $\g$ cannot contain $X \gets R_3$, since $r$ is possibly causal. Neither can $\g$ contain $X - R_3$, since $\langle X, R_3 \rangle \oplus r(R_3,R_n)$ would contradict the definition of $r$ as a shortest proper possibly causal path in $\g$ from $X$ to $\mb{Z}$ that starts undirected. Thus, $\g$ contains $X \to R_3$. In this case, construct the MPDAG $\g^*$ by adding $R_2 \to R_3$ to $\g$ (if it does not already exist) and completing \citeauthor{meek1995causal}'s (\citeyear{meek1995causal}) orientation rules. Note by Lemma \ref{lem:adding-edges-imply} that $\g^*$ still contains $X - R_2$, since $X,R_2 \in \mathrm{Pa}(R_3,\g^*)$.

    With $\g^*$ defined, we let $\g[D]^1$ be a DAG in $[\g^*] \subseteq [\g]$ that contains $X \to R_2$. To see that the path in $\g[D]^1$ corresponding to $r$ in $\g$ takes the form $X \to R_2 \to \dots \to R_n$, note that $r(R_2,R_n)$ is unshielded by the definition of $r$ as a shortest possibly causal path. So when $X \notin \mathrm{Adj}(R_3, \g)$, the claim holds by R1 of \cite{meek1995causal} since we formed $\g[D]^1$ by adding $X \to R_2$ to $\g$. When $X \in \mathrm{Adj}(R_3, \g)$, then the same logic holds since we formed $\g[D]^1$ by adding $X \to R_2 \to R_3$ to $\g$. Further, note that by Lemma \ref{lem:collider-paths2}, $\g$---and therefore $\g[D]^1$---contains the edge $\langle P_2, R_2 \rangle$. Since $\g[D]^1$ is acyclic and has the path $P_2 \to X \to R_2$, then it contains $P_2 \to R_2$ so that $P_2$ is a non-collider on $\langle P_3, P_2, R_2 \rangle$ in $\g[D]^1$.

    Similarly, we let $\g[D]^2$ be a DAG in $[\g^*] \subseteq [\g]$ that contains $X \gets R_2 \to R_3$. (This DAG clearly exists when $\g^*$ contains $X - R_2 \to R_3$. When instead $\g^*$ contains $X - R_2 - R_3$, this DAG exists by Lemma \ref{lem:undirected-imply}.) Then note that the path in $\g[D]^2$ corresponding to $r$ in $\g$ takes the form $X \gets R_2 \to \dots \to R_n$ by R1 of \cite{meek1995causal}, since $r(R_2,R_n)$ is unshielded and possibly causal. To see that $P_2$ is a non-collider on $\langle P_3, P_2, R_2 \rangle$ in $\g[D]^1$, note that by Lemma \ref{lem:collider-paths2}, $\g$ must contain $P_2 \to R_2$; or $P_3 \gets P_2$; or $P_3 - P_2 - R_2$ such that $P_3 \notin \mathrm{Adj}(R_2, \g)$.

    Now that we have chosen $\g[D]^1, \g[D]^2 \in [\g]$, we construct a family of interventional densities $\mb{F^*_i} = \{ f_i(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ compatible with each DAG. Start by constructing a DAG $\g[D]^{1'}$ by removing every edge from $\g[D]^1$ except those on the paths corresponding to $p, q_1, \dots, q_m$, $r$, and $\langle P_2, R_2 \rangle$. Then consider the following linear SEM. Each random variable $V_i \in \mb{V}$ is a linear combination of its parents in $\g[D]^{1'}$ and $\varepsilon_{v_i} \sim N(0, \sigma^2_{v_i})$, where $\{\mb{\varepsilon}_{v_i}: V_i \in \mb{V}\}$ are mutually independent; where the coefficients in the SEM are all $\tfrac{1}{2}$; and where we choose $\sigma^2_{v_i}$ such that $\mathrm{Var}(V_i)=1$ for all $V_i \in \mb{V}$:
    \begin{align} V_i \ \longleftarrow \mspace{-25mu} \sum_{V_j \in \mathrm{Pa}(V_i, \g[D]^{1'})} \mspace{-25mu} \tfrac{1}{2} V_j + \varepsilon_{v_i}.
    \end{align}
    We build $\mb{F^*_1}$ by letting $f_1(\mb{v})$ be the density of the multivariate normal generated by this SEM. For the remaining densities in $\mb{F^*_1}$, we let $f_1(\mb{v} \,|\, do(\mb{x'})) := f_*(\mb{v})$, where $f_*$ is  the density of the multivariate normal generated by taking the SEM in \eqref{thm:alg-complete-4} and replacing $\mb{X'}$ with its interventional value $\mb{x'}$ \citep{pearl2009causality}. Note that $\g[D]^{1'}$ is compatible with $\mb{F^*_1}$ by construction---and therefore, so is $\g[D]^1$ (Lemma \ref{lem:markov-sub}).

    To construct $\mb{F^*_2}$ consider the following linear SEM. Each random variable $V_i \in \mb{V}$ is a linear combination of its parents in $\g[D]^{2'}$ and $\varepsilon_{v_i} \sim N(0, \sigma^2_{v_i})$, where $\{\mb{\varepsilon}_{v_i}: V_i \in \mb{V}\}$ are mutually independent:
    \begin{align} V_i \ &\longleftarrow \mspace{-25mu} \sum_{V_j \in \mathrm{Pa}(V_i, \g[D]^{2'})} \mspace{-25mu} A_{ij} V_j + \varepsilon_{v_i}.
    \end{align}
    Each coefficient $A_{ij}$ in this linear combination is defined by the edge coefficient of $\langle V_i, V_j \rangle$ in $\g[D]^{2'}$. We set the edge coefficients for $\langle X,P_2 \rangle$, $\langle X,R_2 \rangle$, $\langle P_2,R_2 \rangle$ to $-\tfrac{1}{7}$, $\tfrac{6}{7}$, $\tfrac{3}{4}$, respectively, and we set the remaining $A_{ij} = \tfrac{1}{2}$. Further, we choose $\{\mb{\sigma}^2_{v_i}: V_i \in \mb{V}\}$ so that $\mathrm{Var}(V_i)=1$. Then let $f_2(\mb{v})$ be the density of the resulting distribution, which is another multivariate normal with mean vector zero and a covariance matrix with ones on the diagonal. We show below that the off-diagonal entries---which house the variables' covariances---are identical to the covariances from the SEM in \eqref{thm:alg-complete-4}. Thus, in an analogous way to $\mb{F^*_1}$, we can define $\mb{F^*_2} = \{ f_2(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ such that $\g[D]^{2'}$---and therefore $\g[D]^2$---is compatible with $\mb{F^*_2}$ and such that $f_2(\mb{v}) = f_1(\mb{v})$.


    To see that the covariances are identical, note that by Lemma \ref{lem:wright}, the covariances based on $\g[D]' \in \{ \g[D]^{1'}, \g[D]^{2'} \}$ will equal the product of edge coefficients along non-collider paths in $\g[D]'$. Consider the paths in $\g[D]'$ and their colliders. By Lemmas \ref{lem:collider-paths}-\ref{lem:collider-paths2}, the paths in $\g[D]'$ corresponding to $p$, $q_1, \dots, q_m$, $r$ do not overlap anywhere except at $X$ and $C_i$, $i \in \{1, \dots, m\}$. Then note that $\g[D]'$ contains no colliders on $q_1, \dots, q_m$, $\langle R_1, \dots, R_n \rangle$, or $\langle P_3, P_2, R_2, R_3 \rangle$. To see that that $\mb{C}$ is the set of all colliders on $\langle P_1, \dots, P_k \rangle$, note that $p$ is of definite status in $\g$, since $\overline{p} \in \mb{S_1}$ is a definite status path in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ that begins $X \gets P_2$ and has no nodes in $\mb{X} \setminus \{X\}$. However, note that $\g[D]^{1'}$ contains $X \to R_2 \gets P_2$, whereas $\g[D]^{2'}$ contains $P_2 \to X \gets R_2$. Therefore, the claim that the covariances from \eqref{thm:alg-complete-4} and \eqref{thm:alg-complete-5} are identical holds after calculating the following for both models: $\mathrm{Cov}(P_2,X)=\tfrac{1}{2}$, $\mathrm{Cov}(P_2,R_2)=\tfrac{3}{4}$, $\mathrm{Cov}(P_2,R_3)=\tfrac{3}{8}$, $\mathrm{Cov}(X,R_2)=\tfrac{3}{4}$.


    Thus we have two families of interventional densities such that $\g[D]^i$ is compatible with $\mb{F^*_i}$ and such that \eqref{thm:alg-complete-1} holds. To complete Case 2, we show that \eqref{thm:alg-complete-2} holds. It suffices to show that $E[Y \,|\, do(\mb{X}=\mb{1}), \mb{Z}=\mb{0}]$ is not the same under $f_1$ and $f_2$. We start by calculating this expectation under $f_2$. For ease of notation, let $Z_0=R_n$ and let $Z_i = Q_{i_{k_i}}$ for all $i \in \{1, \dots, m\}$.
    \begin{align*}
        \mathbb{E}_{f_2}[Y \,|\, do(&\mb{X}=\mb{1}), \mb{Z} = \mb{0}]\\[.1cm]
            &\,=\, \left. \mathbb{E}_{f_2}[Y \,|\, Z_0, \dots, Z_m] \,\, \right\rvert_{\, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.4cm]
            &\,=\, \left. \begin{bmatrix}
                                \mathrm{Cov}_{f_2}(Y, Z_0) \,\, \cdots \,\, \mathrm{Cov}_{f_2}(Y, Z_m) 
                          \end{bmatrix} 
                          \, \mb{\Sigma}^{-1}
                          \begin{bmatrix}
                                Z_0 \\ \vdots \\ Z_m
                          \end{bmatrix} 
                          \,\, \right\rvert_{\, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.5cm]
            &\,=\, 0,
    \end{align*}
    where $\mb{\Sigma}$ is the covariance matrix of $\{Z_0, \dots, Z_m\}^T$ under $f_2$ (and where $\mb{\Sigma}$ is invertible since $\mb{V}$ is non-degenerate). The first equality follows from Rules 3 and 1 of Pearl's do calculus (Theorem \ref{thm:do-calc}), since $Y \perp_{d} \mb{X} \,|\, \mb{Z}$ in $\g[D]^{2'}_{\overline{\mb{X}}}$; since $Y \perp_{d} \mb{Z} \setminus \{Z_0, \dots, Z_m\} \,|\, Z_0, \dots, Z_m$ in $\g[D]^{2'}$; and since $f_2$ is consistent with $\g[D]^{2'}$. The second equality follows from properties of multivariate normals (see Lemma \ref{lem:mardia}).

    Next, we calculate the same expectation under $f_1$. In each of the subcases below, we show that $\mathbb{E}_{f_1}[Y | do(\mb{X}= \mb{1}), \mb{Z} = \mb{0}]$ is non-zero so that \eqref{thm:alg-complete-2} holds. For these calculations, note that $f_1(y \,|\, do(\mb{x}), \mb{z} )$ is the conditional density of $Y \,|\, \mb{Z}$ under $f_*(\mb{v})$.
    \begin{itemize}
        \item \textbf{SUBCASE 1:}
        When $p'$ has no colliders in $\g[D]^{1'}$,
        \begin{align*}
            \mathbb{E}_{f_1}[Y \,|\, do(\mb{X}= \mb{1}), \mb{Z}= \mb{0}] 
                    &\,=\, \left. \mathbb{E}_{f_*}[Y \,|\, \mb{Z}] \, \right\rvert_{\, \mb{x}=\mb{1}, \, \mb{Z}=\mb{0}}\\
                    &\,=\,  \left. \mathbb{E}_{f_*}[Y \,|\, Z_0] \, \right\rvert_{\, x=1, \, Z_0=0}\\
                    &\,=\,  \left. \mathbb{E}_{f_*}[Y] + \frac{\mathrm{Cov}_{f_*}(Y,Z_0)}{\mathrm{Var}_{f_*}(Z_0)} \cdot \Big(Z_0 - \mathbb{E}_{f_*}[Z_0]\Big) \, \right\rvert_{\, x=1, \, Z_0=0}\\
                    &\,=\,  \frac{\mathrm{Cov}_{f_*}(Y,Z_0)}{\mathrm{Var}_{f_*}(Z_0)} \cdot \big(- \tfrac{1}{2}^{n -1}\big) \\
                    &\,\neq\, 0.
        \end{align*}
        The third equality follows from properties of multivariate normals (see Lemma \ref{lem:mardia}). For the final equality, consider Lemma \ref{lem:sem-covariance}, and note that the SEM that defines $f_*(\mb{v})$ under $do(\mb{X})$ has a matrix of coefficients that are non-zero exactly when $\g[D]^{1'}_{\overline{\mb{X}}}$ contains an edge. It follows that $\mathrm{Cov}_{f_*}(Y,Z_0) \neq 0$, since $\g[D]^{1'}_{\overline{\mb{X}}}$ contains a node in $\{P_2, \dots, P_k\}$ with causal paths to $Y$ and $Z_0$.

        \item \textbf{SUBCASE 2:}
        When $p'$ has at least one collider,
        \begin{align*}
            \mathbb{E}_{f_1}[Y &\,|\, do(\mb{X}= \mb{1}), \mb{Z}= \mb{0}]\\[.1cm]
                    &\,=\, \left. \mathbb{E}_{f_*}[Y \,|\, \mb{Z}] \, \right\rvert_{\, \mb{x}=\mb{1}, \, \mb{Z}=\mb{0}}\\[.1cm]
                    &\,=\, \left. \mathbb{E}_{f_*}[Y \,|\, Z_0, \dots, Z_m] \, \right\rvert_{\, x=1, \, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.4cm]
                    &\,=\, \left. \mathbb{E}_{f_*}[Y] + 
                                  \begin{bmatrix}
                                        \mathrm{Cov}_{f_*}(Y,Z_0) \,\, \cdots \,\, \mathrm{Cov}_{f_*}(Y, Z_m) 
                                  \end{bmatrix} \,
                                        \mb{\Sigma}^{-1} \,\, 
                                  \begin{bmatrix}
                                        Z_0-\mathbb{E}_{f_*}[Z_0]\\
                                        \vdots\\
                                        Z_m-\mathbb{E}_{f_*}[Z_m]
                                  \end{bmatrix} \,\, \right|_{\, \begin{subarray}{l} \,\, x=1, \\ \{Z_0, \dots, Z_m\}=\mb{0}\end{subarray}}\\[-.5cm]
                    &\,=\, \begin{bmatrix}
                                0 \,\, \cdots \,\, 0 & \mathrm{Cov}_{f_*}(Y, Z_m)
                            \end{bmatrix}\,
                                \mb{\Sigma}^{-1} \,\,
                            \begin{bmatrix}
                                -\mathbb{E}_{f_*}[Z_0] \\
                                \mathbf{0}
                            \end{bmatrix}\\
                    &= \tfrac{1}{2}^{k_m'} \cdot \Sigma_{m+1,1} \cdot \big(- \tfrac{1}{2}^{n -1}\big),
        \end{align*}      
        where $k_m'$ is the number of edges on $(-q_m')(Z_m,C_m) \oplus p'(C_m,Y)$; where $\mb{\Sigma}$ is the invertible covariance matrix of $(Z_0, \dots, Z_m)^T$ under $f_*$; and where $\Sigma_{m+1,1}$ is the $(m+1,1)^{th}$ entry of $\mb{\Sigma}^{-1}$. The third equality follows from properties of multivariate normals (see Lemma \ref{lem:mardia}). The last two equalities follow by Lemma \ref{lem:sem-covariance}, since $\g[D]^{1'}_{\overline{\mb{X}}}$ contains no node with causal paths to $Y$ and $Z_i$, $i \in \{0, \dots, m-1\}$, but $\g[D]^{1'}_{\overline{\mb{X}}}$ does contain a node with causal paths to $Y$ and $Z_0$.

        To complete Subcase 2, we show that $\Sigma_{m+1,1} \neq 0$.        
        \begin{align*}
        \mb{\Sigma} \,=\, &
        \begin{blockarray}{cccccc}
        \begin{block}{[cccccc]}
            1   			       & \mathrm{Cov}_{f_*}(Z_0,Z_1) & & & & \\
      	    \mathrm{Cov}_{f_*}(Z_0,Z_1) & 1                      & \ddots & & & \makebox(0,0){\text{\huge0}} \\
                                   & \mathrm{Cov}_{f_*}(Z_1,Z_2) & \ddots & & &	& \\
           	\makebox(0,0){\text{\huge0}}               &                        & \ddots & & \mathrm{Cov}_{f_*}(Z_{m-1}, Z_m) 	& & \\
                                   & & & & 1                     & \mathrm{Cov}_{f_*}(Z_m, Y) \\
                                   & & & & \mathrm{Cov}_{f_*}(Z_m, Y) & 1 \\
        \end{block}
        \end{blockarray}.\\
        \Sigma_{m+1,1} &= \frac{(-1)^{m+2}}{\mathrm{Det}(\mb{\Sigma})} \mathrm{Cov}_{f_*}(Z_0,Z_1) \cdots \mathrm{Cov}_{f_*}(Z_{m-1},Z_m) \\
        &\neq 0.
        \end{align*}
        The final equality follows from Lemma \ref{lem:sem-covariance}, since for each $i \in \{0, \dots, m-1\}$, $\g[D]^{1'}_{\overline{\mb{X}}}$ contains a node in $\{P_2, \dots, P_k\}$ with causal paths to $Z_i$ and $Z_{i+1}$.
    \hfill \rule{1.5ex}{1.5ex}
    \end{itemize}

Reconsider Example ef{ex:id-rule3}, where a causal MPDAG $\g$ is known. We will attempt to use a naive translation of \citeauthor{jaber2022causal}'s 	exttt{CIDP} algorithm to identify the conditional effect of $X$ on $Y$ given $Z$ in this setting. Start by defining $\mb{D} = \mathrm{PossAn}(\mb{Y} \cup \mb{Z}, \g_{\mb{V} \setminus \mb{X}})$ so that $\mb{D} = \{V_1, V_2, V_3, Y, Z\}$. Then define the ordered bucket decomposition (Definition ef{def:obd}) of $\mb{V}$ in $\g$ as $(\mb{B_1},\mb{B_2}, \mb{B_3}, \mb{B_4}) = (\{V_1\}, \{Y\}, \{X, V_2, V_3 \}, \{Z\})$. Since $\mb{B_3} \cap \mb{D} 
eq \emptyset$ and $\mb{B_3} 
ot\subseteq \mb{D}$, we enter the 	exttt{while} loop of the 	exttt{CIDP} algorithm. But $\mb{B_3} \cap \{X\} = \{X\}$, where $X 
ot \perp_{d} Y | Z$ in $\g_{\underline{X}}$. Thus, the algorithm outputs a 	exttt{FAIL}, implying the conditional effect is not identifiable in $\g$. However, we showed in Example ef{ex:id-rule3} that $f(y \,|\, do(x),z) = f(y \,|\, z)$.

This lemma requires the same assumptions as Theorem \ref{thm:id-formula}---that $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$ and no proper possibly causal path from $\mb{X}$ to $\mb{Y}$ starts undirected. Under these assumptions, the lemma claims
    \begin{align}
        f(\mb{b_i} \,|\, \mb{b_{i-1}}, \dots, \mb{b_0}, do(\mb{x}),\mb{z}) = 
        \begin{cases} 
            f(\mb{b_i} \,|\, \mathrm{pa}(\mb{b_i},\g)) & \mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset\\
            f(\mb{b_i} \,|\, \mb{b_i^N}, \mb{z}) & \mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) \neq \emptyset.
        \end{cases} \end{align}

We begin the proof by assuming that a possibly causal path---as given in the statement of Theorem \ref{thm:alg-complete}---exists in the MPDAG $\g$. Based on the given d-separation between $X \in \mb{X}$ and $\mb{Y}$, we consider the following non-empty sets:
    \begin{align}
        \mb{S_1} &= \left\{\begin{array}{ll}
                        \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                        \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                    \end{array}\right\}\text{ and} \nonumber\\
        \mb{S_2} &= \{ \text{ paths in $\mb{S_1}$ with the fewest colliders } \}. \end{align}

\textbf{PART \ref{lem:algo-4-one}}
    Note that this result is analogous to Lemma D.1 of \cite{perkovic2020identifying} for the unconditional causal effect setting. Start by defining the following sets.
    \begin{align*}
        \mb{P_i}      \,=\, &(\cup_{j=0}^{i-1}\mb{B_j} \cup \mb{Z}) \cap \mathrm{Pa}(\mb{B_i}, \g). &&
        \mb{X_{p_i}}  \,=\, \mb{X} \cap \mathrm{Pa}(\mb{B_i}, \g). \\

        \mb{N_i}      \,=\, &(\cup_{j=0}^{i-1} \mb{B_j} \cup \mb{Z}) \setminus \mathrm{Pa}(\mb{B_i}, \g). &&
        \mb{X_{n_i}}  \,=\, \mb{X} \setminus \mathrm{Pa}(\mb{B_i}, \g). \\[0.1in] 

        &&&
        \mb{X'_{n_i}} \,=\, \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}}).
    \end{align*}
    We show the result in the three steps below.
    \begin{align}
        f(\mb{b_i}| \mb{b_{i-1}}, \dots, \mb{b_0}, do(\mb{x}),\mb{z})
                &= f(\mb{b_i}| \mb{p_i}, do(\mb{x})) \\
                &= f(\mb{b_i}| \mb{p_i}, do(\mb{x_{p_i}})) \\
                &= f(\mb{b_i}|\mathrm{pa}(\mb{b_i},\g)). \end{align}
    In order to use Rules 1, 3, and 2 of the do calculus (Theorem \ref{thm:do-calc}) to show the equalities in \eqref{eq:algo-4-one-1}, \eqref{eq:algo-4-one-2}, and \eqref{eq:algo-4-one-3}, respectively, we must show the following.
    \begin{align}
        &(\mb{B_i} \perp_{d} \mb{N_i} \,\,\, | \mb{X}, \mb{P_i})_{\g[D]_{\overline{\mb{X}}}}. \\
        &(\mb{B_i} \perp_{d} \mb{X_{n_i}} | \mb{X_{p_i}}, \mb{P_i})_{\g[D]_{\overline{\mb{X_{p_i}}\mb{X'_{n_i}}}}}. \\
        &(\mb{B_i} \perp_{d} \mb{X_{p_i}} | \mb{P_i})_{\g[D]_{\underline{\mb{X_{p_i}}}}}. \end{align}
    We first show a broader independence claim and complete the proof by showing that each of the independence statements above is a special case of the broader claim.

    \vskip .1in





    \textbf{Broader Claim:}
    Define the sets $\mb{N}$, $\mb{H}$, $\mb{X'}$, and $\mb{N'}$ such that $\mb{N}$, $\mb{H}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint and such that the following hold.
    \begin{align}
        \mb{N}  \phantom{,}&\subseteq\phantom{,} 
                \mb{N_i} \cup \mb{X_{n_i}}
                \,=\, \big(\cup_{j=1}^{i-1} \mb{B_j} \cup \mb{Z} \cup \mb{X} \big) \setminus \mathrm{Pa}(\mb{B_i}, \g). \nonumber\\
        \mb{H}  \phantom{,}&\subseteq\phantom{,}
                \mb{X_{p_i}}
                \,=\, \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g). \nonumber\\
        \mb{X'} \phantom{,}&\subseteq\phantom{,} 
                \mb{X}. \nonumber\\
        \mb{N'} \phantom{,}&\subseteq\phantom{,} 
                \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X'}}}). \nonumber\\[0.1in]

        \mathrm{Pa}(\mb{B_i},\g) \phantom{,}&\subseteq\, \mb{X'} \cup \mb{P_i} \cup \mb{H}. \nonumber\\
        \mb{N} \setminus \mb{N'} \phantom{,}&\subseteq\, \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}. \end{align}
    The broader claim we will show is
    \begin{align}
        &(\mb{B_i} \perp_{d} \big[\mb{N} \cup \mb{H}\big] | \mb{X'}, \mb{P_i})_{\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}}. \end{align}

    Before beginning the proof of this broader claim, note that from the assumptions above, we also have the following.
    \begin{align*}
        \text{There is no poss}&\text{ibly causal path in } \g \text{ from } \tag{$\ast$}\\
        \mb{B_i} \text{ to } &\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}. \nonumber
    \end{align*}
    To see this, note that $\mb{H} \subseteq \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g)$, and by Lemmas \ref{lem:bucket-restrict2} and \ref{lem:algo-4efghi}\ref{lem:algo-4e}, $\big[ \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g) \big] \cap \big( \cup_{j=n}^{\ell} \mb{C_j} \big) = \emptyset$. Thus, $\mb{H} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$. Then by \eqref{eq:algo-4-one-7} and the definition of $\mb{P_i}$, we have $\big( \mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$. The result follow by the fact that $\mb{B_i} \subseteq \mb{C_n}$, Lemma \ref{lem:bucket-restrict2}, and the fact that $\mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset$. 

    \vskip .1in

    We turn to prove the broader claim using a strategy similar to that of the proof of Lemma D.1 of \cite{perkovic2020identifying}. For sake of contradiction, suppose that there is a path from $\mb{B_i}$ to $\mb{N} \cup \mb{H}$ in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ that is d-connecting given $\mb{X'} \cup \mb{P_i}$. Let $p =\langle B_i, \dots, N \rangle$, $B_i \in \mb{B_i}$, $N \in \mb{N} \cup \mb{H}$, be a shortest such path, and let $p^*$ be the corresponding path in $\g$.

    Consider when $p$ begins with an arrow out of $B_i$. If $p$ were causal, then $N \notin \mb{N'}$ since $p$ is in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$. Further, the corresponding path in $\g[D]$ would also be causal, which by Lemma \ref{lem:pc-imply1b} would imply that $p^*$ is a possibly causal path from $\mb{B_i}$ to $\big(\mb{N} \cup \mb{H} \big) \setminus \mb{N'}$. But this contradicts \eqref{eq:algo-4-one-8}. Thus, let $C$ be the closest collider to $B_i$ on $p$. Since $p$ is d-connecting given $\mb{X'} \cup \mb{P_i}$ in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$, then $C \in \mathrm{An}(\mb{P_i},\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}})$. But this implies that there is a causal path in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$---and therefore in $\g[D]$---from $\mb{B_i}$ to $\mb{P_i}$. By Lemma \ref{lem:pc-imply1b}, the corresponding path in $\g$ is possibly causal, which again contradicts \eqref{eq:algo-4-one-8}.

    Consider next when $p$ begins with $B_i \gets A$. By choice of $p$, $A \notin \mb{B_i}$ and so $A \in \mathrm{Pa}(\mb{B_i}, \g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}})$. But $A \notin \mathrm{Pa}(\mb{B_i}, \g)$, since $\mathrm{Pa}(\mb{B_i}, \g) \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$ and $p$ is d-connecting given $\mb{X'} \cup \mb{P_i}$ in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$. Thus, $p^*$ begins with $B_i - A$. If $p^*$ were undirected, then $N \in \mb{C_n}$ and so $N \notin \mb{H} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$. Thus by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4b}, $p^*$ would be a possibly causal path from $\mb{B_i}$ to $N \in \mb{N}$ and $(-p^*)$ would be a possibly causal path from $N \in \mb{N}$ to $\mb{B_i}$. The former contradicts \eqref{eq:algo-4-one-8} when $N \in \mb{N} \setminus \mb{N'}$. The latter contradicts Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e} when $N \in \mb{N'} \subseteq \mb{X}$.

    Since $p^*$ must contain a directed edge, let $T$ be the node closest to $B_i$ on $p^*$ such that $p^*(T, N)$ starts with such an edge. Let $S$ and $U$ be the nodes on $p^*$ immediately preceding and following $T$, respectively. Note that $T \notin \mb{H}$ by choice of $p$. 

    Consider when $p^*$ contains $T \to U$. Note that $p(T,N)$ also contains $T \to U$. When $p(T, N)$ contains at least one collider, then by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4d}, $\g$ contains a causal path from $T$ to $\mb{P_i}$. When instead $p(T,N)$ is causal, then $N \notin \mb{N'}$ since $p$ is in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$. Thus by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4c}, $\g$ contains a causal path from $T$ to $\big(\mb{N} \cup \mb{H} \big) \setminus \mb{N'}$. In either case, $\g$ contains a causal path from $T$ to $\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}$. Since $\g$ also contains $p^*(B_i, T)$---which is possibly causal by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4b} and the fact that $T \notin \mb{H}$---then by Lemma \ref{lem:concat}, $\g$ contains a possibly causal path from $B_i \in \mb{B_i}$ to $\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}$, which contradicts \eqref{eq:algo-4-one-8}.

    Finally, consider when $p^*$ contains $T \gets U$. Then by R1 of \cite{meek1995causal}, $\g$---and therefore $\g[D]$---contains the edge $\langle S, U \rangle$. Note that $\g[D]$ also contains $T \gets U$. By Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4a}, the path in $\g[D]$ corresponding to $p(B_i, T)$ cannot contain colliders on the path in $\g[D]$ corresponding to $p$. Thus, $\g[D]$ contains $S \gets T \gets U$ and therefore $S \gets U$. Further since $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ must also contain $S \gets T \gets U$, then $S \notin \mb{X'} \cup \mb{N'}$ and $U \notin \mb{H}$, and so $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ contains $S \gets U$. But then $p(B_i, S) \oplus \langle S,U \rangle \oplus p(U, N)$ contradicts the choice of $p$.

    \vskip .1in





    \textbf{Special Cases:}
    With the broader claim shown, we now complete the proof by showing that the independence statements in \eqref{eq:algo-4-one-4}, \eqref{eq:algo-4-one-5}, and \eqref{eq:algo-4-one-6} are special cases of \eqref{eq:algo-4-one-9}.

    \eqref{eq:algo-4-one-4}
    Let $\mb{N} = \mb{N_i}$, $\mb{H} = \emptyset$, $\mb{X'} = \mb{X}$, and $\mb{N'} = \emptyset$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{N}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{N} \subseteq \mb{N_i} \cup \mb{X_{n_i}}$ and $\mb{X'} \subseteq \mb{X}$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. Finally, note that $\mb{N} \setminus \mb{N'} = \mb{N_i}$, where $\mb{N_i} \subseteq \cup_{j=1}^{i-1} \mb{B_j} \cup \mb{Z} \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$ by definition.

    \vskip .1in

    \eqref{eq:algo-4-one-5}
    Let $\mb{N} = \mb{X_{n_i}}$, $\mb{H} = \emptyset$, $\mb{X'} = \mb{X_{p_i}}$, and $\mb{N'} = \mb{X'_{n_i}}$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{N}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{N} \subseteq \mb{N_i} \cup \mb{X_{n_i}}$ and $\mb{X'} \subseteq \mb{X}$. Further, $\mb{N'} = \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}}) \subseteq \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X'}}})$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. 

    Finally, to see that $\mb{N} \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$, let $N$ be an arbitrary node in $\mb{N} \setminus \mb{N'} = \mb{X_{n_i}} \cap \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}})$. This implies that there is a causal path in $\g[D]_{\overline{\mb{X_{p_i}}}}$ from $N$ to some $P_i \in \mb{P_i} \subseteq \mathrm{Pa}(\mb{B_i},\g)$. This path is also in $\g[D]$, and thus by Lemma \ref{lem:pc-imply1b}, its corresponding path in $\g$ is possibly causal from $N$ to $\mathrm{Pa}(\mb{B_i},\g)$. Therefore by Lemma \ref{lem:concat}, there is a possibly causal path in $\g$ from $N$ to $\mb{B_i}$. Since $\mb{B_i} \subseteq \mb{C_n}$, then $N \notin \cup_{j=n+1}^{k} \mb{C_j}$ by Lemma \ref{lem:bucket-restrict2}. Further, since $N \in \mb{X}$ and $\mb{B_i} \subseteq \mb{D}$, then $N \notin \mb{C_n}$ by Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e}.

    \vskip .1in

    \eqref{eq:algo-4-one-6}
    Let $\mb{N} = \emptyset$, $\mb{H} = \mb{X_{p_i}}$, $\mb{X'} = \emptyset$, and $\mb{N'} = \emptyset$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{H}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{H} \subseteq \mb{X_{p_i}}$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. Finally, note that $\mb{N} \setminus \mb{N'} = \emptyset \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$.

\textbf{PART \ref{lem:algo-4-one}}
    Note that this result is analogous to Lemma D.1 of \cite{perkovic2020identifying} for the unconditional causal effect setting. Start by defining the following sets.
    \begin{align*}
        \mb{P_i}      \,=\, &(\cup_{j=0}^{i-1}\mb{B_j} \cup \mb{Z}) \cap \mathrm{Pa}(\mb{B_i}, \g). &&
        \mb{X_{p_i}}  \,=\, \mb{X} \cap \mathrm{Pa}(\mb{B_i}, \g). \\

        \mb{N_i}      \,=\, &(\cup_{j=0}^{i-1} \mb{B_j} \cup \mb{Z}) \setminus \mathrm{Pa}(\mb{B_i}, \g). &&
        \mb{X_{n_i}}  \,=\, \mb{X} \setminus \mathrm{Pa}(\mb{B_i}, \g). \\[0.1in] 

        &&&
        \mb{X'_{n_i}} \,=\, \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}}).
    \end{align*}
    We show the result in the three steps below.
    \begin{align}
        f(\mb{b_i}| \mb{b_{i-1}}, \dots, \mb{b_0}, do(\mb{x}),\mb{z})
                &= f(\mb{b_i}| \mb{p_i}, do(\mb{x})) \\
                &= f(\mb{b_i}| \mb{p_i}, do(\mb{x_{p_i}})) \\
                &= f(\mb{b_i}|\mathrm{pa}(\mb{b_i},\g)). \end{align}
    In order to use Rules 1, 3, and 2 of the do calculus (Theorem \ref{thm:do-calc}) to show the equalities in \eqref{eq:algo-4-one-1}, \eqref{eq:algo-4-one-2}, and \eqref{eq:algo-4-one-3}, respectively, we must show the following.
    \begin{align}
        &(\mb{B_i} \perp_{d} \mb{N_i} \,\,\, | \mb{X}, \mb{P_i})_{\g[D]_{\overline{\mb{X}}}}. \\
        &(\mb{B_i} \perp_{d} \mb{X_{n_i}} | \mb{X_{p_i}}, \mb{P_i})_{\g[D]_{\overline{\mb{X_{p_i}}\mb{X'_{n_i}}}}}. \\
        &(\mb{B_i} \perp_{d} \mb{X_{p_i}} | \mb{P_i})_{\g[D]_{\underline{\mb{X_{p_i}}}}}. \end{align}
    We first show a broader independence claim and complete the proof by showing that each of the independence statements above is a special case of the broader claim.

\textbf{Broader Claim:}
    Define the sets $\mb{N}$, $\mb{H}$, $\mb{X'}$, and $\mb{N'}$ such that $\mb{N}$, $\mb{H}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint and such that the following hold.
    \begin{align}
        \mb{N}  \phantom{,}&\subseteq\phantom{,} 
                \mb{N_i} \cup \mb{X_{n_i}}
                \,=\, \big(\cup_{j=1}^{i-1} \mb{B_j} \cup \mb{Z} \cup \mb{X} \big) \setminus \mathrm{Pa}(\mb{B_i}, \g). \nonumber\\
        \mb{H}  \phantom{,}&\subseteq\phantom{,}
                \mb{X_{p_i}}
                \,=\, \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g). \nonumber\\
        \mb{X'} \phantom{,}&\subseteq\phantom{,} 
                \mb{X}. \nonumber\\
        \mb{N'} \phantom{,}&\subseteq\phantom{,} 
                \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X'}}}). \nonumber\\[0.1in]

        \mathrm{Pa}(\mb{B_i},\g) \phantom{,}&\subseteq\, \mb{X'} \cup \mb{P_i} \cup \mb{H}. \nonumber\\
        \mb{N} \setminus \mb{N'} \phantom{,}&\subseteq\, \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}. \end{align}
    The broader claim we will show is
    \begin{align}
        &(\mb{B_i} \perp_{d} \big[\mb{N} \cup \mb{H}\big] | \mb{X'}, \mb{P_i})_{\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}}. \end{align}

    Before beginning the proof of this broader claim, note that from the assumptions above, we also have the following.
    \begin{align*}
        \text{There is no poss}&\text{ibly causal path in } \g \text{ from } \tag{$\ast$}\\
        \mb{B_i} \text{ to } &\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}. \nonumber
    \end{align*}
    To see this, note that $\mb{H} \subseteq \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g)$, and by Lemmas \ref{lem:bucket-restrict2} and \ref{lem:algo-4efghi}\ref{lem:algo-4e}, $\big[ \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g) \big] \cap \big( \cup_{j=n}^{\ell} \mb{C_j} \big) = \emptyset$. Thus, $\mb{H} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$. Then by \eqref{eq:algo-4-one-7} and the definition of $\mb{P_i}$, we have $\big( \mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$. The result follow by the fact that $\mb{B_i} \subseteq \mb{C_n}$, Lemma \ref{lem:bucket-restrict2}, and the fact that $\mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset$. 

    \vskip .1in

    We turn to prove the broader claim using a strategy similar to that of the proof of Lemma D.1 of \cite{perkovic2020identifying}. For sake of contradiction, suppose that there is a path from $\mb{B_i}$ to $\mb{N} \cup \mb{H}$ in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ that is d-connecting given $\mb{X'} \cup \mb{P_i}$. Let $p =\langle B_i, \dots, N \rangle$, $B_i \in \mb{B_i}$, $N \in \mb{N} \cup \mb{H}$, be a shortest such path, and let $p^*$ be the corresponding path in $\g$.

    Consider when $p$ begins with an arrow out of $B_i$. If $p$ were causal, then $N \notin \mb{N'}$ since $p$ is in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$. Further, the corresponding path in $\g[D]$ would also be causal, which by Lemma \ref{lem:pc-imply1b} would imply that $p^*$ is a possibly causal path from $\mb{B_i}$ to $\big(\mb{N} \cup \mb{H} \big) \setminus \mb{N'}$. But this contradicts \eqref{eq:algo-4-one-8}. Thus, let $C$ be the closest collider to $B_i$ on $p$. Since $p$ is d-connecting given $\mb{X'} \cup \mb{P_i}$ in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$, then $C \in \mathrm{An}(\mb{P_i},\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}})$. But this implies that there is a causal path in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$---and therefore in $\g[D]$---from $\mb{B_i}$ to $\mb{P_i}$. By Lemma \ref{lem:pc-imply1b}, the corresponding path in $\g$ is possibly causal, which again contradicts \eqref{eq:algo-4-one-8}.

    Consider next when $p$ begins with $B_i \gets A$. By choice of $p$, $A \notin \mb{B_i}$ and so $A \in \mathrm{Pa}(\mb{B_i}, \g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}})$. But $A \notin \mathrm{Pa}(\mb{B_i}, \g)$, since $\mathrm{Pa}(\mb{B_i}, \g) \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$ and $p$ is d-connecting given $\mb{X'} \cup \mb{P_i}$ in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$. Thus, $p^*$ begins with $B_i - A$. If $p^*$ were undirected, then $N \in \mb{C_n}$ and so $N \notin \mb{H} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$. Thus by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4b}, $p^*$ would be a possibly causal path from $\mb{B_i}$ to $N \in \mb{N}$ and $(-p^*)$ would be a possibly causal path from $N \in \mb{N}$ to $\mb{B_i}$. The former contradicts \eqref{eq:algo-4-one-8} when $N \in \mb{N} \setminus \mb{N'}$. The latter contradicts Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e} when $N \in \mb{N'} \subseteq \mb{X}$.

    Since $p^*$ must contain a directed edge, let $T$ be the node closest to $B_i$ on $p^*$ such that $p^*(T, N)$ starts with such an edge. Let $S$ and $U$ be the nodes on $p^*$ immediately preceding and following $T$, respectively. Note that $T \notin \mb{H}$ by choice of $p$. 

    Consider when $p^*$ contains $T \to U$. Note that $p(T,N)$ also contains $T \to U$. When $p(T, N)$ contains at least one collider, then by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4d}, $\g$ contains a causal path from $T$ to $\mb{P_i}$. When instead $p(T,N)$ is causal, then $N \notin \mb{N'}$ since $p$ is in $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$. Thus by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4c}, $\g$ contains a causal path from $T$ to $\big(\mb{N} \cup \mb{H} \big) \setminus \mb{N'}$. In either case, $\g$ contains a causal path from $T$ to $\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}$. Since $\g$ also contains $p^*(B_i, T)$---which is possibly causal by Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4b} and the fact that $T \notin \mb{H}$---then by Lemma \ref{lem:concat}, $\g$ contains a possibly causal path from $B_i \in \mb{B_i}$ to $\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}$, which contradicts \eqref{eq:algo-4-one-8}.

    Finally, consider when $p^*$ contains $T \gets U$. Then by R1 of \cite{meek1995causal}, $\g$---and therefore $\g[D]$---contains the edge $\langle S, U \rangle$. Note that $\g[D]$ also contains $T \gets U$. By Lemma \ref{lem:algo-4abcd}\ref{lem:algo-4a}, the path in $\g[D]$ corresponding to $p(B_i, T)$ cannot contain colliders on the path in $\g[D]$ corresponding to $p$. Thus, $\g[D]$ contains $S \gets T \gets U$ and therefore $S \gets U$. Further since $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ must also contain $S \gets T \gets U$, then $S \notin \mb{X'} \cup \mb{N'}$ and $U \notin \mb{H}$, and so $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ contains $S \gets U$. But then $p(B_i, S) \oplus \langle S,U \rangle \oplus p(U, N)$ contradicts the choice of $p$.

\textbf{Broader Claim:}
    Define the sets $\mb{N}$, $\mb{H}$, $\mb{X'}$, and $\mb{N'}$ such that $\mb{N}$, $\mb{H}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint and such that the following hold.
    \begin{align}
        \mb{N}  \phantom{,}&\subseteq\phantom{,} 
                \mb{N_i} \cup \mb{X_{n_i}}
                \,=\, \big(\cup_{j=1}^{i-1} \mb{B_j} \cup \mb{Z} \cup \mb{X} \big) \setminus \mathrm{Pa}(\mb{B_i}, \g). \nonumber\\
        \mb{H}  \phantom{,}&\subseteq\phantom{,}
                \mb{X_{p_i}}
                \,=\, \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g). \nonumber\\
        \mb{X'} \phantom{,}&\subseteq\phantom{,} 
                \mb{X}. \nonumber\\
        \mb{N'} \phantom{,}&\subseteq\phantom{,} 
                \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X'}}}). \nonumber\\[0.1in]

        \mathrm{Pa}(\mb{B_i},\g) \phantom{,}&\subseteq\, \mb{X'} \cup \mb{P_i} \cup \mb{H}. \nonumber\\
        \mb{N} \setminus \mb{N'} \phantom{,}&\subseteq\, \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}. \end{align}
    The broader claim we will show is
    \begin{align}
        &(\mb{B_i} \perp_{d} \big[\mb{N} \cup \mb{H}\big] | \mb{X'}, \mb{P_i})_{\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}}. \end{align}

Before beginning the proof of this broader claim, note that from the assumptions above, we also have the following.
    \begin{align*}
        \text{There is no poss}&\text{ibly causal path in } \g \text{ from } \tag{$\ast$}\\
        \mb{B_i} \text{ to } &\big(\mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'}. \nonumber
    \end{align*}
    To see this, note that $\mb{H} \subseteq \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g)$, and by Lemmas \ref{lem:bucket-restrict2} and \ref{lem:algo-4efghi}\ref{lem:algo-4e}, $\big[ \mb{X} \cap \mathrm{Pa}(\mb{B_i},\g) \big] \cap \big( \cup_{j=n}^{\ell} \mb{C_j} \big) = \emptyset$. Thus, $\mb{H} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$. Then by \eqref{eq:algo-4-one-7} and the definition of $\mb{P_i}$, we have $\big( \mb{N} \cup \mb{H} \cup \mb{P_i} \big) \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$. The result follow by the fact that $\mb{B_i} \subseteq \mb{C_n}$, Lemma \ref{lem:bucket-restrict2}, and the fact that $\mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset$.

\textbf{Special Cases:}
    With the broader claim shown, we now complete the proof by showing that the independence statements in \eqref{eq:algo-4-one-4}, \eqref{eq:algo-4-one-5}, and \eqref{eq:algo-4-one-6} are special cases of \eqref{eq:algo-4-one-9}.

    \eqref{eq:algo-4-one-4}
    Let $\mb{N} = \mb{N_i}$, $\mb{H} = \emptyset$, $\mb{X'} = \mb{X}$, and $\mb{N'} = \emptyset$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{N}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{N} \subseteq \mb{N_i} \cup \mb{X_{n_i}}$ and $\mb{X'} \subseteq \mb{X}$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. Finally, note that $\mb{N} \setminus \mb{N'} = \mb{N_i}$, where $\mb{N_i} \subseteq \cup_{j=1}^{i-1} \mb{B_j} \cup \mb{Z} \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$ by definition.

    \vskip .1in

    \eqref{eq:algo-4-one-5}
    Let $\mb{N} = \mb{X_{n_i}}$, $\mb{H} = \emptyset$, $\mb{X'} = \mb{X_{p_i}}$, and $\mb{N'} = \mb{X'_{n_i}}$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{N}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{N} \subseteq \mb{N_i} \cup \mb{X_{n_i}}$ and $\mb{X'} \subseteq \mb{X}$. Further, $\mb{N'} = \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}}) \subseteq \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X'}}})$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. 

    Finally, to see that $\mb{N} \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$, let $N$ be an arbitrary node in $\mb{N} \setminus \mb{N'} = \mb{X_{n_i}} \cap \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}})$. This implies that there is a causal path in $\g[D]_{\overline{\mb{X_{p_i}}}}$ from $N$ to some $P_i \in \mb{P_i} \subseteq \mathrm{Pa}(\mb{B_i},\g)$. This path is also in $\g[D]$, and thus by Lemma \ref{lem:pc-imply1b}, its corresponding path in $\g$ is possibly causal from $N$ to $\mathrm{Pa}(\mb{B_i},\g)$. Therefore by Lemma \ref{lem:concat}, there is a possibly causal path in $\g$ from $N$ to $\mb{B_i}$. Since $\mb{B_i} \subseteq \mb{C_n}$, then $N \notin \cup_{j=n+1}^{k} \mb{C_j}$ by Lemma \ref{lem:bucket-restrict2}. Further, since $N \in \mb{X}$ and $\mb{B_i} \subseteq \mb{D}$, then $N \notin \mb{C_n}$ by Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e}.

    \vskip .1in

    \eqref{eq:algo-4-one-6}
    Let $\mb{N} = \emptyset$, $\mb{H} = \mb{X_{p_i}}$, $\mb{X'} = \emptyset$, and $\mb{N'} = \emptyset$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{H}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{H} \subseteq \mb{X_{p_i}}$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. Finally, note that $\mb{N} \setminus \mb{N'} = \emptyset \subseteq \cup_{j=1}^{n-1} \mb{C_j} \cup \mb{Z}$.

\eqref{eq:algo-4-one-5}
    Let $\mb{N} = \mb{X_{n_i}}$, $\mb{H} = \emptyset$, $\mb{X'} = \mb{X_{p_i}}$, and $\mb{N'} = \mb{X'_{n_i}}$. Since $\mb{X}$, $\mb{Z}$, and $\mb{D}$ are pairwise disjoint, then $\mb{N}$, $\mb{X'}$, $\mb{B_i}$, and $\mb{P_i}$ are pairwise disjoint by definition. Clearly, $\mb{N} \subseteq \mb{N_i} \cup \mb{X_{n_i}}$ and $\mb{X'} \subseteq \mb{X}$. Further, $\mb{N'} = \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}}) \subseteq \mb{X_{n_i}} \setminus \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X'}}})$. Then note that $\mathrm{Pa}(\mb{B_i},\g) = \mb{X_{p_i}} \cup \mb{P_i} \subseteq \mb{X'} \cup \mb{P_i} \cup \mb{H}$. 

    Finally, to see that $\mb{N} \setminus \mb{N'} \subseteq \cup_{j=1}^{n-1} \mb{C_j}$, let $N$ be an arbitrary node in $\mb{N} \setminus \mb{N'} = \mb{X_{n_i}} \cap \mathrm{An}(\mb{P_i}, \g[D]_{\overline{\mb{X_{p_i}}}})$. This implies that there is a causal path in $\g[D]_{\overline{\mb{X_{p_i}}}}$ from $N$ to some $P_i \in \mb{P_i} \subseteq \mathrm{Pa}(\mb{B_i},\g)$. This path is also in $\g[D]$, and thus by Lemma \ref{lem:pc-imply1b}, its corresponding path in $\g$ is possibly causal from $N$ to $\mathrm{Pa}(\mb{B_i},\g)$. Therefore by Lemma \ref{lem:concat}, there is a possibly causal path in $\g$ from $N$ to $\mb{B_i}$. Since $\mb{B_i} \subseteq \mb{C_n}$, then $N \notin \cup_{j=n+1}^{k} \mb{C_j}$ by Lemma \ref{lem:bucket-restrict2}. Further, since $N \in \mb{X}$ and $\mb{B_i} \subseteq \mb{D}$, then $N \notin \mb{C_n}$ by Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e}.

\textbf{PART \ref{lem:algo-4-two}}
    Let $\mb{B_i^D}= \cup_{j=0}^{i-1}\mb{B_j} \cap \mathrm{PossDe}(\mb{X},\g)$. We show the result in the steps below.
    \begin{align}
        f(\mb{b_i}| \mb{b_{i-1}}, \dots, \mb{b_0}, do(\mb{x}), \mb{z})
                &= f(\mb{b_i}| \mb{b_i^N}, do(\mb{x}),\mb{z}) \\
                &= f(\mb{b_i}| \mb{b_i^N}, \mb{z}). \end{align}
    In order to use Rules 1 and 3 of the do calculus (Theorem \ref{thm:do-calc}) to show the equalities in \eqref{eq:algo-4-two-1} and \eqref{eq:algo-4-two-2}, respectively, we must show the following.
    \begin{align}
        &(\mb{B_i} \perp_{d} \mb{B_i^D} | \mb{X}, \mb{Z}, \mb{B_i^N})_{\g[D]_{\overline{\mb{X}}}}. \\
        &(\mb{B_i} \perp_{d} \mb{X} \,\,\,\,| \mb{B_i^N}, \mb{Z})_{\g[D]_{\overline{\mb{W}}}}, \end{align}
    where we let $\mb{W} = \mb{X} \setminus \mathrm{An}(\mb{B_i^N} \cup \mb{Z}, \g[D])$. We prove these independencies below.


    \vskip .1in


    \eqref{eq:algo-4-two-3} 
    Suppose for sake of contradiction that there is a path in $\g[D]_{\overline{\mb{X}}}$ from $\mb{B_i}$ to $\mb{B_i^D}$ that is d-connecting given $\mb{X} \cup \mb{Z} \cup \mb{B_i^N}$. Let $q=\langle B_i=Q_0, \dots, Q_m=B_i^D \rangle$, $m \ge 1$, be a shortest such path and let $q^*$ be the corresponding path in $\g$. Further, let $\mb{C_h}$, $h \in \{1, \dots, n-1\}$, be the bucket in $\mb{V}$ such that $B_i^D \in \mb{C_h}$. 

    Before beginning the proof, note the following.
    \begin{align*}
        \text{There is no ca}&\text{usal path in } \g[D]_{\overline{\mb{X}}} \text{ from } \tag{$\ast\ast$}\\
        \mb{C_h} \text{ to } &\mb{B_i} \cup \mb{Z} \cup \mb{B_i^N}. \nonumber
    \end{align*}    
    To see this, suppose for sake of contradiction that such a path $p$ did exist, and let $p^*$ be the corresponding path in $\g$. Since the corresponding path in $\g[D]$ is also causal, then by Lemma \ref{lem:pc-imply1b}, $p^*$ is a possibly causal path from $\mb{C_h}$ to $\mb{B_i} \cup \mb{Z} \cup \mb{B_i^N}$, where by Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4e}, $\mb{C_h} \subseteq \mathrm{De}(\mb{X}, \g)$. Thus by Lemma \ref{lem:concat}, $\g$ contains a possibly causal path from $\mb{X}$ to $\mb{B_i} \cup \mb{Z} \cup \mb{B_i^N}$. But by assumption, definition, and Lemma \ref{lem:algo-4efghi}\ref{lem:algo-4f}, $(\mb{B_i} \cup \mb{Z} \cup \mb{B_i^N}) \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$. With the claim shown, we turn to find a contradiction in the two cases below.

    \textbf{Case 1:} 
    Consider when $q$ contains $Q_{m-1} \gets B_i^D$. Note that $(-q)$ cannot be causal from $B_i^D \in \mb{C_h}$ to $B_i \in \mb{B_i}$ by \eqref{eq:algo-4-one-10} and therefore, must contain a collider. Let $\mb{L}$ be the set containing the collider closest to $B_i^D$ on $q$ and all of its descendants in $\g[D]_{\overline{\mb{X}}}$. Since $q$ is d-connecting given $\mb{X} \cup \mb{Z} \cup \mb{B_i^N}$ in $\g[D]_{\overline{\mb{X}}}$, then $\mb{L}$ must contain an element in $\mb{Z} \cup \mb{B_i^N}$. But since $\mb{L} \subseteq \mathrm{De}(\mb{C_h},\g[D]_{\overline{\mb{X}}})$, this contradicts \eqref{eq:algo-4-one-10}.

    \textbf{Case 2:}
