\ref{lem:algo-4c} 
    Let $q_1$ be causal and let $q^*$ begin with $Q_0 \to Q_1$. Note that $q_2$ is also causal. Suppose for sake of contradiction that $q^*$ is shielded. That is, $\g$---and therefore $\g[D]$---contains at least one edge $\langle Q_d, Q_{d+2} \rangle$ for some $d \in \{0, \dots, k-2 \}$. Since $q_2$ is causal, $\g[D]$ must contain $Q_d \to Q_{d+2}$. Further, because $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ contains $Q_d \to Q_{d+1} \to Q_{d+2}$, then $Q_{d+2} \notin \mb{X'} \cup \mb{N'}$ and $Q_d \notin \mb{H}$, and so $\g[D]_{\overline{\mb{X'}\mb{N'}}\underline{\mb{H}}}$ must also contain $Q_d \to Q_{d+2}$. But then the path $p_1(B,Q_d) \oplus \langle Q_d, Q_{d+2} \rangle \oplus p_1(Q_{d+2},N)$ contradicts the choice of $p_1$. Thus, $q^*$ is unshielded. 

    Since $q_2$ is causal, $q^*$ can only contain edges of the form $Q_i - Q_{i+1}$ and $Q_i \to Q_{i+1}$ for all $i \in \{0, \dots, k-1\}$. Since additionally $q^*$ begins with $Q_0 \to Q_1$ and is unshielded, the result follows by R1 of \cite{meek1995causal}.

To calculate these expectations, we first want to apply Rules 1-3 of the do calculus (Theorem \ref{thm:do-calc}). Since $f_i(\mb{v} | do(\mb{x}))$, $i \in \{1,2\}$, is consistent with $\g[D]^{i'}$, we apply these rules using graphical relationships in $\g[D]^{i'}$. Because the path in $\g[D]^{i'}$ corresponding to $q_i$, $i \in \{1,2\}$, does not contain nodes in $\mb{Z}$ or $\mb{X} \setminus \{X\}$, then $Y \perp_{d} \mb{Z} | \mb{X}$ and $Y \perp_{d} \mb{X} \setminus \{X\} | X$ in $\g[D]^{i'}_{\overline{\mb{X}}}$. Further, $Y \perp_{d} X$ in $\g[D]^{1'}_{\underline{X}}$ and $Y \perp_{d} X$ in $\g[D]^{2'}_{\overline{X}}$. Thus by Rules 1-3 of the do calculus (Theorem \ref{thm:do-calc}), the following hold.
    \begin{align*}
        E_1[Y | do(\mb{X}=\mb{1}), \mb{Z}] &= E_1[Y | do(X=1)] = E_1[Y|X=1] := a.\\
        E_2[Y | do(\mb{X}=\mb{1}), \mb{Z}] &= E_2[Y | do(X=1)] = E_2[Y] := b,
    \end{align*}    
    where $E_i, i \in \{1,2\}$ is the expectation under $f_i$. To calculate $a$ and $b$, we rely on the observational density $f(\mb{v})$, which was constructed using $\g[D]^{1'}$. By Lemma \ref{lem:mardia}, $a$ equals the covariance of $X$ and $Y$ under $f(\mb{v})$, and by Lemma \ref{lem:wright}, $\mathrm{Cov}(X,Y)$ equals the product of all edge coefficients in $\g[D]^{1'}$, which were chosen to be in $(0,1)$. Therefore, $a \neq 0$. But by definition of $f(\mb{v})$, $b=0$.

Note that by the truncated factorization in Equation \eqref{eq:trunc-fact}, $f(\mb{v})$ is Markov compatible with $\g[D]^*$. Thus by Lemma \ref{lem:markov-equiv},
    \begin{align}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]^*) \cup \mathrm{Pa}(V_i,\g[D]^*) \big) \Big] | \mathrm{Pa}(V_i, \g[D]^*) \end{align}
    for all $V_i \in \mb{V}$, where $\perp\!\!\!\!\perp$ indicates independence with respect to $f(\mb{v})$.

Further, since $\mathrm{De}(V_i,\g[D]^*) \subseteq \mathrm{De}(V_i,\g[D])$, then $\mathrm{De}(V_i,\g[D]^*) \cap \mathrm{Pa}(V_i,\g[D]) = \emptyset$ and thus $\mathrm{Pa}(V_i,\g[D]) \subseteq \mb{V} \setminus \mathrm{De}(V_i, \g[D]^*)$. Therefore it follows from \eqref{eq:markov-sub-1} that
    \begin{align} 
        V_i \perp\!\!\!\!\perp \Big[ \mathrm{Pa}(V_i,\g[D]) \setminus \mathrm{Pa}(V_i,\g[D]^*) \Big] \,\, \Big| \,\, \mathrm{Pa}(V_i,\g[D]^*). \end{align}

Let $f(\mb{v} | do(\mb{x'}))$, $\mb{X'} \subseteq \mb{V}$, be an arbitrary density in $\mb{F^*}$. Then by definition and \eqref{eq:markov-sub-2}
    \begin{align*}
        f(\mb{v} | do(\mb{x'})) &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D]^*)) \mathbbm{1}(\mb{X'} = \mb{x'})\\
                                &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D])) \mathbbm{1}(\mb{X'} = \mb{x'}).
    \end{align*}

Let $p = \langle Z=V_1, \dots, V_k=Y \rangle$, $Z \in \mb{Z}$, $Y \in \mb{Y}$, $k > 1$.

    \ref{lem:do-helper1-one}
    Let $V_i$, $i \in \{2, \dots, k-1\}$, be an arbitrary collider on $p$. For sake of contradiction, suppose $\g[D]$ contains the edge $\langle V_{i-1}, V_{i+1} \rangle$. Define $q = p(Z,V_{i-1}) \oplus \langle V_{i-1}, V_{i+1} \rangle \oplus p(V_{i+1}, Y)$. By the choice of $p$, $q$ must be blocked by $\mb{X} \cup \mb{W}$. Since $V_{i-1}$ and $V_{i+1}$ are non-colliders on $p$, $q$ must be blocked by a collider at either $V_{i-1}$ or $V_{i+1}$. Without loss of generality, pick $V_{i-1}$ so that $\g[D]$ contains $V_{i-2} \to V_{i-1} \gets V_{i+1}$, where no descendant of $V_{i-1}$ is in $\mb{X} \cup \mb{W}$. However, since $p$ is d-connecting given $\mb{X} \cup \mb{W}$ and $p$ contains $V_{i-1} \to V_i \gets V_{i+1}$, at least one descendant of $V_i$---and therefore of $V_{i-1}$---in $\g[D]$ must be in $\mb{X} \cup \mb{W}$.

Suppose there is a path in $\g = (\mb{V, E})$ from $X \in \mb{X}$ to $\mb{Y} \cup \mb{Z}$ that does not contain $\mb{X} \setminus \{X\}$, is possibly causal, starts undirected---and where $\mb{Y} \not\perp_{d} X \,|\, \mb{X} \setminus \{X\}, \mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. We want to show that the conditional effect of $\mb{X}$ on $\mb{Y}$ given $\mb{Z}$ is not identifiable in $\g$. Since ${\mb{Y} \not\perp_{d} X \,|\, \mb{X} \setminus \{X\}, \mb{Z}}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$, the following sets must be non-empty:
    \begin{align*}
        \mb{S_1} &= \left\{\begin{array}{ll}
                        \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                        \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                    \end{array}\right\} \text{ and}\\
        \mb{S_2} &= \hspace{.05in}\{ \hspace{.05in}\text{paths in $\mb{S_1}$ with the fewest colliders} \hspace{.05in}\}.
    \end{align*}
    Then consider the following set:
    \begin{align*}
        \mb{S_3} &= \hspace{.05in}\{ \hspace{.05in}\text{paths in } \mb{S_2} \text{ that start undirected}\hspace{.05in}\}. \hspace{1.8in}
    \end{align*}
    We divide the remainder of the proof into two cases based on whether $\mb{S_3} = \emptyset$. In both cases, we consider DAGs $\g[D]^1, \g[D]^2 \in [\g]$ with paths in the sets above. To show the conditional effect is not identifiable in $\g$, it suffices to show that each $\g[D]^i$ is compatible with a family of interventional densities $\mb{F^*_i} = \{ f_i(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ such that the following hold.
    \begin{align}
        f_1(\mb{v}) &\,=\, f_2(\mb{v}). \\
        f_1(\mb{y} \,|\, do(\mb{x}), \mb{z}) & \,\neq\, f_2(\mb{y} \,|\, do(\mb{x}), \mb{z}). \end{align}

